	{
		data = 
		{
			actions = 
			{
				
				{
					data = 
					{
						aType = "Lua",
						actionLua = "-- Mount Rokkon: owned, pull-scoped draw state. Territory 1155 / 1156.\n-- Independent preferences shared by all Mount Rokkon reactions.\nif _G.RokkonSettingsFileReady~=2 then\n local folder=GetLuaModsPath()..[[TensorReactions\\Settings\\]]\n local path=folder..[[Mountrokkon.lua]]\n local defaults={role=1,towerMode=1,finalClones=1,enabled=true,arrows=true,timers=true,tts=true,gaze=true,fukoKB=true,goraiKB=true,triple=true,mokoBackups=false}\n local C=jacobRokkonOptions\n if not C then\n  C={}\n  if FileExists(path) then local saved=FileLoad(path);if type(saved)==\"table\" then C=saved end end\n end\n for key,value in pairs(defaults) do\n  if type(C[key])~=type(value) then C[key]=value end\n end\n C.role=math.max(1,math.min(5,math.floor(C.role)))\n C.towerMode=math.max(1,math.min(3,math.floor(C.towerMode)))\n C.finalClones=math.max(1,math.min(2,math.floor(C.finalClones)))\n function C.save()\n  if not FolderExists(folder) then FolderCreate(folder) end\n  local values={};for key in pairs(defaults) do values[key]=C[key] end\n  FileSave(path,values)\n end\n jacobRokkonOptions=C;C.save()\n _G.RokkonSettingsFileReady=2\nend\nif not data.jacobRokkon or data.jacobRokkon.version~=9 then\n    if data.jacobRokkon then data.jacobRokkon.cleanup() end\n    local s={version=9,hazards={},shapes={},steps={},spreads={},stacks={},towers={},circleArena=false}\n    data.jacobRokkon=s\n    s.red=TensorCore.getCachedDrawer(0x300000FF,nil,0x500000FF,0xFF0000FF,2)\n    s.green=TensorCore.getCachedDrawer(0x3000FF00,nil,0x5000FF00,0xFF00FF00,2)\n    function s.own(uuid,deadline)\n        if uuid then s.shapes[uuid]=deadline end\n        return uuid\n    end\n    function s.remove(uuid)\n        if uuid then Argus.deleteTimedShape(uuid); s.shapes[uuid]=nil end\n    end\n    function s.clearGuide()\n        s.remove(s.arrow);s.remove(s.destination);s.arrow=nil;s.destination=nil;s.guide=nil\n    end\n    function s.cleanup()\n        for u in pairs(s.shapes) do Argus.deleteTimedShape(u) end\n        if s.gazeUntil then\n            TensorCore.API.TensorACR.toggleLockFace(false)\n            TensorCore.API.TensorACR.setHardLockFace(false)\n        end\n        s.shapes={};s.hazards={};s.steps={};s.spreads={};s.stacks={};s.towers={}\n        s.arrow=nil;s.destination=nil;s.guide=nil;s.gazeUntil=nil;s.eye=nil;s.swipeUntil=nil\n        s.myTower=nil;s.myGhost=nil;s.towerGatherAt=nil;s.towerAssigned=nil;s.towerCalled=nil;s.largeSpreads={}\n        s.statusCircle=nil;s.statusKey=nil;s.statusDrawn={};s.ghostDanger={};s.rearPreview=nil\n        s.gTowerMode=nil;s.gTowers={};s.gMyTower=nil\n        s.triple=nil;s.moko=nil;s.mUpwell=nil;s.mokoLateral=nil\n        s.clouds={};s.cloudForecast={};s.noblePending={};s.cloudStage=nil;s.cloudMode=nil;s.cloudGuideUntil=nil;s.nobleGuideUntil=nil;s.charges={};s.rings={};s.noblePlan=nil;s.nobleGoal=nil;s.nobleSolved=nil;s.defamationGoals=nil;s.defamationCalled=nil;s.defamationAttempted=nil;s.breaths=0\n        s.exaUntil=nil;s.exaCenter=nil;s.gExa=nil;s.g2=nil;s.gLimit=nil;s.gEarlyPairs=nil;s.swipeCallUntil=nil;s.cloudAnnounced=nil\n        s.flameUntil=nil;s.hammerUntil=nil;s.hammerOrb=nil;s.hammerTarget=nil\n        s.statusReadUntil=nil;s.statusReadAt=nil;s.gOrderReadUntil=nil\n    end\n    function s.role(ent)\n        local p=ent or TensorCore.mGetPlayer()\n        local r=jacobRokkonOptions.role\n        local me=TensorCore.mGetPlayer()\n        if r>1 and p and me and p.id==me.id then return r-1 end\n        if not p then return nil end\n        local j=p.job\n        if j==19 or j==21 or j==32 or j==37 then return 1 end\n        if j==24 or j==28 or j==33 or j==40 then return 2 end\n        local melee=j==20 or j==22 or j==30 or j==34 or j==39 or j==41\n        if r==4 and p.id~=me.id then return 4 end\n        if r==5 and p.id~=me.id then return 3 end\n        if melee then return 3 end\n        return 4\n    end\n    function s.call(text,red)\n        TensorCore.addAlertText(3000,text,1.2,red and 3 or 1,jacobRokkonOptions.tts,100)\n    end\n    function s.timer(ms,p,color)\n        if jacobRokkonOptions.timers then\n            AnyoneCore.addWorldTextCountdown(ms,{x=p.x,y=p.y+1,z=p.z},color or 0xFFFFFFFF,true,1.3)\n        end\n    end\n    function s.magicJob()\n        local p=TensorCore.mGetPlayer()\n        if not p then return false end\n        local j=p.job\n        return j==24 or j==25 or j==27 or j==28 or j==33 or j==35 or j==40 or j==42\n    end\n    function s.add(h)\n        h.start=h.start or Now();h.deadline=h.deadline or Now()+5000\n        local ms=math.max(1,h.deadline-Now())\n        local delay=(h.cloud or h.noble) and 0 or math.max(0,h.start-Now())\n        local p=h.pos\n        if h.noble then\n            local first=h.deadline\n            for _,v in ipairs(s.hazards)do if v.noble and v.deadline>Now() and v.deadline<first then first=v.deadline end end\n            if h.deadline>first+2500 then s.hazards[#s.hazards+1]=h;return h end\n        end\n        if h.kind==\"circle\" then h.uuid=s.own(s.red:addTimedCircle(ms,p.x,p.y,p.z,h.r,delay,false,true),h.deadline)\n        elseif h.kind==\"donut\" then h.uuid=s.own(s.red:addTimedDonut(ms,p.x,p.y,p.z,h.inner,h.r,delay,false,true),h.deadline)\n        elseif h.kind==\"cone\" then h.uuid=s.own(s.red:addTimedCone(ms,p.x,p.y,p.z,h.r,h.angle,h.heading,delay,false,true),h.deadline)\n        elseif h.kind==\"rect\" then h.uuid=s.own(s.red:addTimedRect(ms,p.x,p.y,p.z,h.length,h.width,h.heading,delay,false,true),h.deadline)\n        elseif h.kind==\"centered\" then h.uuid=s.own(s.red:addTimedCenteredRect(ms,p.x,p.y,p.z,h.length,h.width,h.heading,delay,false,true),h.deadline) end\n        s.hazards[#s.hazards+1]=h\n        if not h.noTimer then s.timer(ms,p) end\n        return h\n    end\n    function s.danger(h,x,z)\n        local dx,dz=x-h.pos.x,z-h.pos.z\n        local d2=dx*dx+dz*dz\n        if h.kind==\"circle\" then return d2<(h.r+0.6)^2 end\n        if h.kind==\"donut\" then return d2>(h.inner-0.6)^2 and d2<(h.r+0.6)^2 end\n        local along=dx*math.sin(h.heading)+dz*math.cos(h.heading)\n        if h.kind==\"cone\" then\n            return d2<(h.r+0.6)^2 and (d2<0.36 or along/math.sqrt(d2)>math.cos(h.angle/2+0.025))\n        end\n        local across=dx*math.cos(h.heading)-dz*math.sin(h.heading)\n        local low=h.kind==\"centered\" and -h.length/2 or 0\n        local high=h.kind==\"centered\" and h.length/2 or h.length\n        return along>low-0.6 and along<high+0.6 and math.abs(across)<h.width/2+0.6\n    end\n    function s.safe(x,z,deadline)\n        for _,h in ipairs(s.hazards) do\n            if h.start<=deadline and h.deadline>=deadline-400 and h.deadline<=deadline+800 and s.danger(h,x,z) then return false end\n        end\n        return true\n    end\n    function s.guideTo(pos,deadline,key)\n        if not jacobRokkonOptions.arrows then s.clearGuide();return end\n        local p=TensorCore.mGetPlayer()\n        if not p then return end\n        local ms=math.max(750,deadline-Now()+750)\n        s.guide={pos=pos,deadline=deadline,key=key}\n        if s.destination then\n            s.green:updateTimedCircle(s.destination,ms,pos.x,pos.y,pos.z,0.8,0,false,true)\n            s.shapes[s.destination]=deadline\n        else s.destination=s.own(s.green:addTimedCircle(ms,pos.x,pos.y,pos.z,0.8,0,false,true),deadline) end\n        local dist=math.sqrt((pos.x-p.pos.x)^2+(pos.z-p.pos.z)^2)\n        if dist<0.8 then s.remove(s.arrow);s.arrow=nil;return end\n        local heading=TensorCore.getHeadingToTarget(p.pos,pos)\n        if s.arrow then\n            s.green:updateTimedArrow(s.arrow,ms,p.pos.x,p.pos.y,p.pos.z,heading,math.max(0.1,dist-0.8),0.35,0.8,1.1,0,false)\n            s.shapes[s.arrow]=deadline\n        else s.arrow=s.own(s.green:addTimedArrow(ms,p.pos.x,p.pos.y,p.pos.z,heading,math.max(0.1,dist-0.8),0.35,0.8,1.1,0,false),deadline) end\n    end\n    function s.avoid(deadline,center,radius,key)\n        local p=TensorCore.mGetPlayer()\n        if not p then return end\n        local best,score=nil,math.huge\n        -- Keep an established safe destination until the next mechanic changes it.\n        if s.guide and s.guide.key==key and s.safe(s.guide.pos.x,s.guide.pos.z,deadline) then\n            s.guideTo(s.guide.pos,deadline,key);return\n        end\n        for x=center.x-radius+1,center.x+radius-1,1 do\n            for z=center.z-radius+1,center.z+radius-1,1 do\n                local arena=not (s.circleArena and center.x==0) or (x-center.x)^2+(z-center.z)^2<(radius-1)^2\n                if arena and s.safe(x,z,deadline) then\n                    local d=(x-p.pos.x)^2+(z-p.pos.z)^2\n                    if d<score then best,score={x=x,y=p.pos.y,z=z},d end\n                end\n            end\n        end\n        if best then s.guideTo(best,deadline,key) else s.clearGuide() end\n    end\n    function s.eyeSpot()\n        local v=s.eye\n        if not v then return end\n        local me=TensorCore.mGetPlayer()\n        if not me then return end\n        local role=s.role()\n        local out=v.advanced and not v.out or not v.advanced and v.out\n        local radius=out and 17 or 5.5\n        local now=Now()\n        local spread=s.spreads[me.id]\n        local spreadFirst=spread and spread>now and (not s.stackDeadline or spread<s.stackDeadline)\n        local north=role==1 or role==2\n        if not spreadFirst then\n            local countN,countS=0,0\n            for _,e in pairs(TensorCore.getEntityGroupList(\"Party\")) do\n                if s.stacks[e.id] and s.stacks[e.id]>now then\n                    local r=s.role(e)\n                    if r==1 or r==2 then countN=countN+1 else countS=countS+1 end\n                end\n            end\n            -- Healer / melee adjust when both stack markers are in the same role group.\n            if (countN==2 or countS==2) and (role==2 or role==3) then north=not north end\n        end\n        local dx,dz=0,north and -radius or radius\n        if spreadFirst then\n            dx=(role==1 or role==4) and radius/math.sqrt(2) or -radius/math.sqrt(2)\n            dz=north and -radius/math.sqrt(2) or radius/math.sqrt(2)\n        end\n        s.guideTo({x=v.pos.x+dx,y=me.pos.y,z=v.pos.z+dz},v.advanced and v.second or v.first,\"eye-personal\")\n    end\n    function s.statusDraws(now)\nif s.ghostPulseDraw then s.ghostPulseDraw(now) end\n        for id,deadline in pairs(s.spreads)do if deadline<=now then s.spreads[id]=nil end end\n        for id,deadline in pairs(s.stacks)do if deadline<=now then s.stacks[id]=nil end end\n        s.statusDrawn=s.statusDrawn or{}\n        for _,kind in ipairs({'spread','pair'})do\n            local entries=kind=='spread' and s.spreads or s.stacks\n            for id,deadline in pairs(entries)do\n                local e=TensorCore.mGetEntity(id)\n                local key=kind..':'..id..':'..math.floor(deadline/500)\n                if e and deadline-now<=4000 and not s.statusDrawn[key]then\n                    local ms=math.max(1,deadline-now)\n                    local radius=kind=='spread' and(s.spreadRadius or 6)or(s.stackRadius or 5)\n                    local drawer=kind=='spread' and s.red or s.green\n                    s.own(drawer:addTimedCircleOnEnt(ms,id,radius,0,false,true),deadline)\n                    AnyoneCore.addTimedWorldTextOnEnt(ms,kind=='spread' and 'Spread' or 'Pair stack',id,\n                        kind=='spread' and 0xFF3333FF or 0xFF33FF33,true,1.2,1.5)\n                    if jacobRokkonOptions.timers then\n                        AnyoneCore.addWorldTextCountdown(ms,{x=e.pos.x,y=e.pos.y+2.4,z=e.pos.z},\n                            kind=='spread' and 0xFF3333FF or 0xFF33FF33,true,1.2)\n                    end\n                    s.statusDrawn[key]=deadline\n                end\n            end\n        end\n        for key,t in pairs(s.statusDrawn)do if t<=now then s.statusDrawn[key]=nil end end\n        local me=TensorCore.mGetPlayer();if not me then return end\n        local spread=s.spreads[me.id];local stack\n        for _,t in pairs(s.stacks)do if not stack or t<stack then stack=t end end\n        local deadline=spread and(not stack or spread<stack)and spread or stack\n        if not deadline then s.statusKey=nil;return end\n        local isSpread=deadline==spread\n        local key=tostring(math.floor(deadline/500))..(isSpread and ':spread' or ':pair')\n        if s.statusKey~=key then\n            s.statusKey=key;s.call(isSpread and 'Spread' or 'Pair stack',false)\n        end\n    end\nend\n\nlocal s=data.jacobRokkon\nif not s.spec then s.spec={[33820]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Avoid the rear cleave\",[\"r\"]=25,[\"angle\"]=1.5707963267948966},[33859]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Avoid the rear cleave\",[\"r\"]=25,[\"angle\"]=1.5707963267948966},[33795]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"r\"]=6},[33834]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"r\"]=6},[33796]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=2},[33835]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=2},[33797]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=6},[33836]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=6},[33798]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=12},[33837]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=12},[33803]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Dodge the swipes\",[\"r\"]=40,[\"angle\"]=3.141592653589793},[33804]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Dodge the swipes\",[\"r\"]=40,[\"angle\"]=3.141592653589793},[33842]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Dodge the swipes\",[\"r\"]=40,[\"angle\"]=3.141592653589793},[33843]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Dodge the swipes\",[\"r\"]=40,[\"angle\"]=3.141592653589793},[33810]={[\"kind\"]=\"donut\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Move IN\",[\"inner\"]=8,[\"r\"]=30},[33849]={[\"kind\"]=\"donut\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Move IN\",[\"inner\"]=8,[\"r\"]=30},[34097]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=300,[\"z\"]=-120},[\"call\"]=\"Dodge the cone\",[\"r\"]=60,[\"angle\"]=0.7853981633974483},[34131]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=300,[\"z\"]=-120},[\"call\"]=\"Dodge the cone\",[\"r\"]=60,[\"angle\"]=0.7853981633974483},[34065]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=300,[\"z\"]=-120},[\"call\"]=nil,[\"length\"]=46,[\"width\"]=5},[34113]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=300,[\"z\"]=-120},[\"call\"]=nil,[\"length\"]=46,[\"width\"]=5},[34257]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=\"Move OUT\",[\"r\"]=6},[34304]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=\"Move OUT\",[\"r\"]=6},[34258]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"length\"]=60,[\"width\"]=10},[34305]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"length\"]=60,[\"width\"]=10},[34261]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"length\"]=60,[\"width\"]=10},[34308]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"length\"]=60,[\"width\"]=10},[34259]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"length\"]=60,[\"width\"]=30},[34306]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"length\"]=60,[\"width\"]=30},[34250]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34251]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34252]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34253]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34297]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34298]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34299]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34300]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34499]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34500]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34501]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34502]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34507]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34508]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34509]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34510]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=23,[\"angle\"]=4.71238898038469},[34244]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=60,[\"angle\"]=4.71238898038469},[34245]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=60,[\"angle\"]=4.71238898038469},[34246]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=60,[\"angle\"]=4.71238898038469},[34294]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=60,[\"angle\"]=4.71238898038469},[34295]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=60,[\"angle\"]=4.71238898038469},[34296]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=60,[\"angle\"]=4.71238898038469},[34255]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=10},[34302]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=10},[34727]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=10},[34729]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=10},[34256]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=20},[34303]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=20},[34728]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=20},[34730]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=20},[34390]={[\"kind\"]=\"circle\",[\"arena\"]=nil,[\"call\"]=\"Move OUT\",[\"r\"]=10},[34408]={[\"kind\"]=\"circle\",[\"arena\"]=nil,[\"call\"]=\"Move OUT\",[\"r\"]=10},[34394]={[\"kind\"]=\"circle\",[\"arena\"]=nil,[\"call\"]=\"Move OUT\",[\"r\"]=10},[34412]={[\"kind\"]=\"circle\",[\"arena\"]=nil,[\"call\"]=\"Move OUT\",[\"r\"]=10},[34389]={[\"kind\"]=\"donut\",[\"arena\"]=nil,[\"call\"]=\"Move IN\",[\"inner\"]=5,[\"r\"]=30},[34407]={[\"kind\"]=\"donut\",[\"arena\"]=nil,[\"call\"]=\"Move IN\",[\"inner\"]=5,[\"r\"]=30},[34391]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=nil,[\"r\"]=12,[\"angle\"]=2.0943951023931953},[34409]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=nil,[\"r\"]=12,[\"angle\"]=2.0943951023931953},[34437]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34438]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34440]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34441]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34404]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34429]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34422]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34430]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34439]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=8},[34442]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=8}} end\nlocal s=data.jacobRokkon\nif not s.goraiHelpers then\n    s.goraiHelpers=true\n    function s.gTower(t)\n        local p=TensorCore.mGetPlayer()\n        if not p or not s.gTowerMode or s.gTowerMode~=1 then return end\n        local blue=t.index%2==0\n        local order=blue and s.gBlueOrder or s.gOrangeOrder\n        if order~=t.wave then return end\n        t.mine=true\n        s.own(s.green:addTimedCircle(t.deadline-Now(),t.pos.x,t.pos.y,t.pos.z,3.3,0,false,true),t.deadline)\n        s.timer(t.deadline-Now(),t.pos,0xFF33FF33)\n        if not s.gMyTower or t.wave<s.gMyTower.wave then s.gMyTower=t end\n        s.call((t.wave>s.gResolvedWave+1 and \"Next: \" or \"\")..(blue and \"Blue tower\" or \"Orange tower\"),false)\n        if s.gMyTower==t then s.guideTo(t.pos,t.deadline,\"gorai-tower-\"..t.wave) end\n    end\nend\n\nlocal s=data.jacobRokkon\nif not s.mokoHelpers then\n    s.mokoHelpers=true\n    function s.tripleStep(v,pos,heading,inside,deadline)\n        if v.shapes then for _,u in ipairs(v.shapes) do s.remove(u) end end\n        v.pos=pos;v.heading=heading;v.deadline=deadline;v.inside=inside\n        local cone=s.add({kind=\"cone\",pos=pos,r=60,angle=math.pi*1.5,heading=heading,deadline=deadline,caster=v.boss,noTimer=true})\n        local radial=s.add({kind=inside and \"donut\" or \"circle\",pos=pos,inner=6,r=inside and 40 or 6,deadline=deadline,caster=v.boss,noTimer=true})\n        v.shapes={cone.uuid,radial.uuid}\n        s.timer(math.max(1,deadline-Now()),pos)\n        local h=heading+math.pi\n        local r=inside and 3.5 or 8\n        s.clearGuide()\n        s.guideTo({x=pos.x+r*math.sin(h),y=pos.y,z=pos.z+r*math.cos(h)},deadline,\"triple-\"..v.index)\n        if v.called~=v.index then s.call((inside and \"IN\" or \"OUT\")..\": green wedge\",false);v.called=v.index end\n    end\nend\n\nlocal s=data.jacobRokkon\nif not s.shishioHelpers then\n    s.shishioHelpers=true;s.clouds={};s.cloudForecast={};s.breaths=0;s.rings={}\n    function s.cloudChain(line)\n        local radius=({8,12,23})[s.breaths]\n        if not radius then return end\n        local times={}\n        for id,c in pairs(s.clouds) do\n            local dx,dz=c.pos.x-line.pos.x,c.pos.z-line.pos.z\n            local along=dx*math.sin(line.heading)+dz*math.cos(line.heading)\n            local across=dx*math.cos(line.heading)-dz*math.sin(line.heading)\n            if math.abs(along)<=30 and math.abs(across)<=7 then times[id]=line.deadline+1100 end\n        end\n        for _=1,32 do\n            local changed=false\n            for id,c in pairs(s.clouds) do\n                if times[id] then\n                    for other,d in pairs(s.clouds) do\n                        if other~=id and (c.pos.x-d.pos.x)^2+(c.pos.z-d.pos.z)^2<=radius^2 then\n                            local t=times[id]+1100\n                            if not times[other] or t<times[other] then times[other]=t;changed=true end\n                        end\n                    end\n                end\n            end\n            if not changed then break end\n        end\n        for id,deadline in pairs(times) do\n            local old=s.cloudForecast[id]\n            if not old or deadline<old.deadline then\n                if old then s.remove(old.uuid);old.deadline=0 end\n                local c=s.clouds[id]\n                local h=s.add({kind=\"circle\",pos=c.pos,r=radius,start=deadline-1100,deadline=deadline,\n                    caster=id,cloud=true,noTimer=true})\n                s.cloudForecast[id]=h\n            end\n        end\n    end\n    function s.nobleRing(pos,h)\n        s.rings=s.rings or {}\n        local seen=false\n        for _,q in ipairs(s.rings)do if (q.x-pos.x)^2+(q.z-pos.z)^2<.01 then seen=true;break end end\n        local last=s.charges and s.charges[#s.charges]\n        if not last then\n            s.noblePending=s.noblePending or{};s.noblePending[#s.noblePending+1]={pos=pos,heading=h};return\n        end\n        if not s.danger(last,pos.x,pos.z) then\n            local from=s.nobleEnd\n            local dx,dz=pos.x-from.x,pos.z-from.z\n            if math.abs(dx)<.1 then dx=0 end\n            if math.abs(dz)<.1 then dz=0 end\n            local len=math.sqrt(dx*dx+dz*dz)\n            if len<.1 then return end\n            local ux,uz=dx/len,dz/len\n            local tx=math.abs(ux)>.001 and ((ux>0 and 20 or -20)-from.x)/ux or math.huge\n            local tz=math.abs(uz)>.001 and ((uz>0 and -80 or -120)-from.z)/uz or math.huge\n            local length=math.min(tx,tz)\n            if length<=0 or length>60 then return end\n            last=s.add({kind=\"rect\",pos=from,length=length,width=12,heading=TensorCore.getHeadingToTarget(from,pos),\n                start=last.deadline,deadline=last.deadline+1400,noTimer=true,noble=true})\n            s.charges[#s.charges+1]=last\n            s.nobleEnd={x=from.x+ux*length,y=from.y,z=from.z+uz*length}\n        end\n        s.add({kind=\"centered\",pos=pos,length=10,width=100,heading=h,start=last.deadline,\n            deadline=last.deadline+800,noTimer=true,noble=true})\n        if not seen then s.rings[#s.rings+1]=pos end\n        s.noblePlan=nil;s.nobleGoal=nil;s.nobleSolved=nil\n    end\nend\n\nlocal s=data.jacobRokkon\n-- Release only Rokkon-owned mechanic state when the replay clock discontinuously seeks.\nlocal clock=TensorReactions_CurrentCombatTimer\nlocal tick=Now()\nlocal seek=s.clockGuardVersion~=1 or (s.lastCombatClock and (clock<s.lastCombatClock-0.5 or (clock>s.lastCombatClock+5 and tick-(s.lastClockTick or tick)<1000)))\nif seek then\n s.cleanup()\n s.wail=nil;s.g2=nil;s.gLimit=nil;s.gExa=nil;s.gEarlyPairs=nil\n s.cloudRouteCache=nil;s.cloudRevision=(s.cloudRevision or 0)+1\n s.swipeCallUntil=nil;s.cloudAnnounced=nil\n if RokkonWorldText then RokkonWorldText.entries={} end\n s.clockGuardVersion=1\nend\ns.lastCombatClock=clock;s.lastClockTick=tick\n\nif s.ownedCleanupVersion~=2 then\n local previousCleanup=s.cleanup\n s.cleanup=function()\n  previousCleanup()\n  s.wail=nil;s.g2=nil;s.gLimit=nil;s.gExa=nil;s.gEarlyPairs=nil\n  s.ghostAwaitFinal=nil;s.ghostReleaseAt=nil;s.ghostPulseCount=nil;s.ghostPulseAt=nil;s.ghostPhaseUntil=nil\n  s.cloudRouteCache=nil;s.cloudAnnounced=nil;s.swipeCallUntil=nil\n  if RokkonWorldText then RokkonWorldText.entries={} end\n end\n s.ownedCleanupVersion=2\nend\nlocal now=Now()\nif not jacobRokkonOptions.enabled then s.cleanup();self.used=true;return end\nlocal p=TensorCore.mGetPlayer()\nif not p then return end\n-- Mechanic-owned helpers; no changes to the shared callout renderer.\nif s.approvedP1Version~=2 then\n s.approvedP1Version=2\n function s.ghostPulseDraw(now)\n  for id,g in pairs(s.ghostDanger or {})do\n   local e=TensorCore.mGetEntity(id)\n   if e then g.pos={x=e.pos.x,y=e.pos.y,z=e.pos.z} end\n   local activation=g.activation\n   if now>=g.deadline or (s.ghostPulseCount or 0)>=8 and now>(s.ghostPulseAt or now)+300 then\n    s.remove(g.uuid);s.ghostDanger[id]=nil\n   elseif activation and now>=activation-1000 and now<=activation+300 and g.pos then\n    local q=g.pos;local ms=math.max(1,activation+300-now)\n    if g.uuid and g.drawActivation~=activation then s.remove(g.uuid);g.uuid=nil end\n    if not g.drawPos or (q.x-g.drawPos.x)^2+(q.z-g.drawPos.z)^2>.01 or not g.uuid then\n     s.remove(g.uuid)\n     g.uuid=s.own(s.red:addTimedCircle(ms,q.x,q.y,q.z,6,0,false,true),activation+300)\n     g.drawPos={x=q.x,z=q.z};g.drawActivation=activation\n    end\n   elseif g.uuid then s.remove(g.uuid);g.uuid=nil end\n  end\n end\n function s.nobleGuide(now,p,deadline)\n  if not s.nobleGuideUntil or now>s.nobleGuideUntil then return false end\n  -- Four native rings establish the complete charge arrangement. No guessed gap.\n  if not s.rings or #s.rings<4 then s.clearGuide();return true end\n  if not s.noblePlan then\n   s.noblePlan={}\n   for _,h in ipairs(s.hazards)do if h.noble then s.noblePlan[#s.noblePlan+1]=h end end\n  end\n  if not s.nobleSolved then\n   s.nobleSolved=true\n   local best,score\n   for x=-18,18 do for z=-118,-82 do\n    local inside=not s.circleArena or x*x+(z+100)^2<=18^2\n    local safe=inside\n    if safe then for _,h in ipairs(s.noblePlan)do if s.danger(h,x,z)then safe=false;break end end end\n    if safe then\n     local d=(x-p.pos.x)^2+(z-p.pos.z)^2\n     if not score or d<score then best={x=x,y=p.pos.y,z=z};score=d end\n    end\n   end end\n   s.nobleGoal=best\n  end\n  if s.nobleGoal then s.guideTo(s.nobleGoal,deadline,'noble-common-gap') else s.clearGuide() end\n  return true\n end\n function s.defamationGuide(now,p)\n  if not s.largeSpreads or not s.largeSpreads[p.id] or s.largeSpreads[p.id]<=now then return false end\n  if (s.ghostPulseCount or 0)<8 then s.clearGuide();return true end\n  local marked={}\n  for id,t in pairs(s.largeSpreads)do\n   local e=TensorCore.mGetEntity(id)\n   if t>now and e then marked[#marked+1]=e end\n  end\n  if #marked~=2 or #s.towers~=2 then s.clearGuide();return true end\n  table.sort(marked,function(a,b)local ar,br=s.role(a),s.role(b);return ar==br and a.id<b.id or ar<br end)\n  if not s.defamationAttempted then\n   s.defamationAttempted=true\n   local corners={};local d=s.circleArena and 18/math.sqrt(2) or 18\n   for _,x in ipairs({-d,d})do for _,z in ipairs({-100-d,-100+d})do\n    local good=true\n    for _,tower in ipairs(s.towers)do\n     if (x-tower.pos.x)^2+(z-tower.pos.z)^2<19.6^2 then good=false;break end\n    end\n    if good and s.safe(x,z,s.largeSpreads[p.id])then corners[#corners+1]={x=x,y=p.pos.y,z=z}end\n   end end\n   local best,score\n   for i,a in ipairs(corners)do for j,b in ipairs(corners)do\n    if i~=j and (a.x-b.x)^2+(a.z-b.z)^2>=30.6^2 then\n     local cost=(a.x-marked[1].pos.x)^2+(a.z-marked[1].pos.z)^2+(b.x-marked[2].pos.x)^2+(b.z-marked[2].pos.z)^2\n     if not score or cost<score then best={[marked[1].id]=a,[marked[2].id]=b};score=cost end\n    end\n   end end\n   s.defamationGoals=best\n  end\n  local q=s.defamationGoals and s.defamationGoals[p.id]\n  if q then\n   s.guideTo(q,s.largeSpreads[p.id],'defamation-corner')\n   if not s.defamationCalled then s.defamationCalled=true;s.call('Large spread: your green corner',false)end\n  else s.clearGuide() end\n  return true\n end\nend\n-- Move only the early prediction. The actual Slither cast replaces it normally.\nif s.rearPreview and now<s.rearPreview.deadline then\n local h=s.rearPreview;local boss=TensorCore.mGetEntity(h.caster)\n if boss then\n  local q=boss.pos;local heading=q.h+math.pi\n  if (q.x-h.pos.x)^2+(q.z-h.pos.z)^2>.01 or 1-math.cos(heading-h.heading)>.00005 then\n   s.remove(h.uuid);h.pos={x=q.x,y=q.y,z=q.z};h.heading=heading\n   h.uuid=s.own(s.red:addTimedCone(h.deadline-now,q.x,q.y,q.z,h.r,h.angle,heading,0,false,true),h.deadline)\n  end\n end\nend\n-- Noble previews use the same 2.5-second horizon as the reference.\nlocal nobleFirst\nfor _,h in ipairs(s.hazards)do if h.noble and h.deadline>now and (not nobleFirst or h.deadline<nobleFirst)then nobleFirst=h.deadline end end\nfor _,h in ipairs(s.hazards)do if h.noble then\n local show=nobleFirst and h.deadline>now and h.deadline<=nobleFirst+2500\n if not show then s.remove(h.uuid);h.uuid=nil\n elseif not h.uuid then\n  local q=h.pos;local ms=h.deadline-now\n  if h.kind=='rect' then h.uuid=s.own(s.red:addTimedRect(ms,q.x,q.y,q.z,h.length,h.width,h.heading,0,false,true),h.deadline)\n  elseif h.kind=='centered' then h.uuid=s.own(s.red:addTimedCenteredRect(ms,q.x,q.y,q.z,h.length,h.width,h.heading,0,false,true),h.deadline)end\n end\nend end\n\n-- Bounded Moko draw controller. Assignment state is pull-owned in data, never saved.\nif s.mokoControllerVersion~=1 then\n s.mokoControllerVersion=1\n local function point(x,z,y)return{x=x,y=y,z=z}end\n local function dist(a,b)return(a.x-b.x)^2+(a.z-b.z)^2 end\n local function rotate(q,a)return{x=q.x*math.cos(a)+q.z*math.sin(a),z=q.z*math.cos(a)-q.x*math.sin(a)}end\n local function heading(q)return TensorCore.getHeadingToTarget({x=0,y=0,z=0},{x=q.x,y=0,z=q.z})end\n local function unit(q)local d=math.sqrt(q.x*q.x+q.z*q.z);if d<.1 then return nil end;return{x=q.x/d,z=q.z/d}end\n function s.mokoCall(m,key,text)\n  if m.callKey~=key then m.callKey=key;s.call(text,false)end\n end\n function s.mokoCone(m,id,c)\n  if not c.locked or not c.pos or (c.hits or 0)>=2 or m.kind=='scarlet'and m.cleaveDone then return nil end\n  local tells=m.tells[id];if not tells or #tells<1 then return nil end\n  local h=c.heading+(c.headingReady and 0 or tells[1])\n  return{kind='cone',pos=c.pos,heading=h,r=m.kind=='scarlet'and 60 or 23,angle=math.pi*1.5,deadline=c.deadline}\n end\n function s.mokoSafe(m,x,z,t)\n  if math.abs(x+200)>19.41 or math.abs(z)>19.41 then return false end\n  for _,h in ipairs(s.hazards)do\n   local archer=m and m.kind=='soldiers'and(h.spell==34255 or h.spell==34256 or h.spell==34302 or h.spell==34303 or h.spell==34727 or h.spell==34728 or h.spell==34729 or h.spell==34730)\n   if not archer and h.start<=t and h.deadline>=t-400 and h.deadline<=t+800 and s.danger(h,x,z)then return false end\n  end\n  if m then\n   for _,a in pairs(m.archers)do\n    if a.deadline>=Now()-300 and a.deadline<=t+1000 and(x-a.pos.x)^2+(z-a.pos.z)^2<(a.r+.35)^2 then return false end\n   end\n   for id,c in pairs(m.clones)do\n    local a=s.mokoCone(m,id,c)\n    if not(m.kind=='soldiers'and jacobRokkonOptions.finalClones==1)and a and a.deadline>=Now()-300 and s.danger(a,x,z)then return false end\n   end\n   if not m.lockedAt then for _,a in pairs(m.hands)do if a.deadline>=Now()-300 and s.danger(a,x,z)then return false end end end\n  end\n  return true\n end\n function s.mokoFacing(m,p,h,deadline)\n  local ms=math.max(1,deadline-Now());local q=p.pos\n  if m.face then s.green:updateTimedArrow(m.face,ms,q.x,q.y+.15,q.z,h,3,.35,.8,1.1,0,false);s.shapes[m.face]=deadline\n  else m.face=s.own(s.green:addTimedArrow(ms,q.x,q.y+.15,q.z,h,3,.35,.8,1.1,0,false),deadline)end\n end\n function s.mokoDropFace(m)if m.face then s.remove(m.face);m.face=nil end end\n function s.mokoUpwell(now,p)\n  local u=s.mUpwell;if not u then return false end\n  local active=false;local first\n  for _,a in pairs(u.initial)do if not a.done and now<a.deadline+700 then active=true;if not first or a.deadline<first then first=a.deadline end end end\n  for _,l in ipairs(u.lanes)do if l.left>0 then active=true;if not first or l.deadline<first then first=l.deadline end end end\n  if not active or now>u.untilTime then\n   for _,a in pairs(u.initial)do s.remove(a.uuid)end\n   for _,l in ipairs(u.lanes)do s.remove(l.uuid)end\n   s.mUpwell=nil;if s.guide and s.guide.key=='moko-upwell'then s.clearGuide()end;return false\n  end\n  for _,a in pairs(u.initial)do\n   local show=not a.done and now<a.deadline+300 and a.deadline<=first+1200\n   if not show then s.remove(a.uuid);a.uuid=nil\n   elseif not a.uuid then local q=a.pos;a.uuid=s.own(s.red:addTimedCenteredRect(math.max(1,a.deadline-now),q.x,q.y,q.z,60,10,a.heading,0,false,true),a.deadline)end\n  end\n  for _,l in ipairs(u.lanes)do\n   local show=l.left>0 and now<=l.deadline+600 and l.deadline<=first+1200\n   if not show then s.remove(l.uuid);l.uuid=nil\n   elseif not l.uuid then local q=l.pos;l.uuid=s.own(s.red:addTimedCenteredRect(math.max(1,l.deadline+600-now),q.x,q.y,q.z,60,5,l.heading,0,false,true),l.deadline+600)end\n  end\n  local function safe(x,z)\n   if math.abs(x+200)>18.5 or math.abs(z)>18.5 then return false end\n   for _,a in pairs(u.initial)do if not a.done and a.deadline<=now+4500 and s.danger(a,x,z)then return false end end\n   for _,l in ipairs(u.lanes)do\n    if l.left>0 and l.deadline<=now+4500 then\n     for k=0,math.min(1,l.left-1)do\n      local a={kind='centered',pos=point(l.pos.x+k*l.dx,l.pos.z+k*l.dz,p.pos.y),length=60,width=5,heading=l.heading}\n      if s.danger(a,x,z)then return false end\n     end\n    end\n   end\n   return true\n  end\n  -- Permit the next mechanic only when the remaining native lanes allow its actual destination.\n  local remaining=0;local pending=false\n  for _,a in pairs(u.initial)do if not a.done then pending=true end end\n  for _,l in ipairs(u.lanes)do remaining=math.max(remaining,l.left)end\n  if not pending and remaining<=2 and s.triple and s.triple.pos and s.triple.heading then\n   local v=s.triple;local r=v.inside and 3.5 or 8;local h=v.heading+math.pi\n   if safe(v.pos.x+r*math.sin(h),v.pos.z+r*math.cos(h))then return false end\n  end\n  local key=tostring(u.revision)..':'..tostring(first)..':'..math.floor(now/1000)\n  if u.goal and safe(u.goal.x,u.goal.z)then s.guideTo(u.goal,first,'moko-upwell');return true end\n  u.goal=nil\n  if u.attempt~=key then\n   u.attempt=key;u.goal=nil;local score\n   for x=-218,-182 do for z=-18,18 do if safe(x,z)then\n    local q=point(x,z,p.pos.y);local d=dist(q,p.pos)\n    if not score or d<score then score=d;u.goal=q end\n   end end end\n  end\n  if u.goal then s.guideTo(u.goal,first,'moko-upwell')else s.clearGuide()end\n  s.mokoCall(u,'upwell','Follow the cleared lines; wait for the green cleave spot')\n  return true\n end\n function s.mokoScarletPlan(m,players,t,isSpread)\n  local rolePlayers={};for _,e in ipairs(players)do local r=s.role(e);if not r or rolePlayers[r]then return nil end;rolePlayers[r]=e end\n  for r=1,4 do if not rolePlayers[r]then return nil end end\n  if not isSpread then\n   local support,dps=0,0\n   for r,e in pairs(rolePlayers)do if s.stacks[e.id]and s.stacks[e.id]>Now()then if r<=2 then support=support+1 else dps=dps+1 end end end\n   if support==2 or dps==2 then rolePlayers[2],rolePlayers[3]=rolePlayers[3],rolePlayers[2]end\n  end\n  local tether;for _,id in pairs(m.tethers)do tether=id end\n  local tetherRole;for r,e in pairs(rolePlayers)do if e.id==tether then tetherRole=r end end\n  local best,score\n  for x=-215,-185,2 do for z=-15,15,2 do for turn=0,3 do\n   local a=turn*math.pi/2;local goals={};local valid=true;local cost=0\n   for r=1,4 do\n    local dx,dz\n    if isSpread then dx=({0,-3.4,3.4,0})[r];dz=({-3.4,0,0,3.4})[r]\n    else\n     dx=r<=2 and -2.6 or 2.6;dz=(r==1 or r==3)and -.65 or .65\n     if tetherRole and r~=tetherRole and(r<=2)==(tetherRole<=2)and not m.lockedAt then dx=dx+(dx<0 and 1.5 or -1.5)end\n    end\n    local d=rotate({x=dx,z=dz},a)\n    local e=rolePlayers[r]\n    -- The jump target stages outside the other three, then rejoins after lock.\n    if e.id==tether and not m.lockedAt then local u=unit(d);d.x=d.x+3.5*u.x;d.z=d.z+3.5*u.z end\n    local q=point(x+d.x,z+d.z,players[1].pos.y)\n    if not s.mokoSafe(m,q.x,q.z,t)then valid=false;break end\n    goals[e.id]=q;cost=cost+dist(q,e.pos)\n    if m.lockedAt and dist(q,e.pos)>math.max(1,(t-Now())/1000*5.5-.4)^2 then valid=false;break end\n    if e.id==tether then cost=cost-2*((q.x+200)^2+q.z^2)end\n   end\n   if valid and tether and not m.lockedAt then\n    local q=goals[tether];local tell=m.tells[m.boss]\n    if not tell or not tell[1] then valid=false\n    else\n     local inward=heading({x=x-q.x,z=z-q.z});local face=inward-math.pi-tell[1]\n     local origin=point(q.x-3*math.sin(face),q.z-3*math.cos(face),q.y)\n     local cone={kind='cone',pos=origin,r=60,angle=math.pi*1.5,heading=face+tell[1]}\n     for id,pq in pairs(goals)do if id~=tether and s.danger(cone,pq.x,pq.z)then valid=false;break end end\n     goals.face=face;goals.tether=tether\n    end\n   end\n   if valid and(not score or cost<score)then best=goals;score=cost end\n  end end end\n  return best\n end\n function s.mokoShadowPlan(m,players)\n  local sourceIDs={};local unmarked={};local marked={}\n  for id,target in pairs(m.tethers)do sourceIDs[#sourceIDs+1]=id;marked[target]=true end\n  if #sourceIDs~=2 or m.near==nil then return nil end;table.sort(sourceIDs)\n  for _,e in ipairs(players)do if not marked[e.id]then unmarked[#unmarked+1]=e end end\n  if #unmarked~=2 then return nil end;table.sort(unmarked,function(a,b)return a.id<b.id end)\n  local a=TensorCore.mGetEntity(m.tethers[sourceIDs[1]]);local b=TensorCore.mGetEntity(m.tethers[sourceIDs[2]])\n  if not a or not b then return nil end\n  local function same(x,y)return(s.role(x)<=2)==(s.role(y)<=2)end\n  if (same(a,unmarked[2])and not same(a,unmarked[1]))or(same(b,unmarked[1])and not same(b,unmarked[2]))then unmarked[1],unmarked[2]=unmarked[2],unmarked[1]end\n  local plan={};local handEW\n  for _,h in pairs(m.hands)do handEW=math.abs(h.pos.x+200)>math.abs(h.pos.z);break end\n  if handEW==nil then return nil end\n  for i,id in ipairs(sourceIDs)do\n   local clone=TensorCore.mGetEntity(id);if not clone then return nil end\n   local dir={x=clone.pos.x+200<0 and -1 or 1,z=0};if handEW then dir={x=0,z=dir.x}end\n   local tr=m.near and 19 or 12;local br=m.near and 12 or 19\n   local target=m.tethers[id];plan[target]=point(-200+tr*dir.x,tr*dir.z,clone.pos.y)\n   plan[unmarked[i].id]=point(-200+br*dir.x,br*dir.z,clone.pos.y)\n   plan['face:'..target]=heading({x=(tr-br)*dir.x,z=(tr-br)*dir.z})\n  end\n  return plan\n end\n function s.mokoSoldierPlan(m,players,t)\n  if not m.blue then return nil end\n  local x,z=m.blue.x+200,m.blue.z\n  -- The short coordinate gives the blue shot axis; TH takes its opposite cardinal.\n  local support=math.abs(x)>math.abs(z)and{x=0,z=z>0 and -1 or 1}or{x=x>0 and -1 or 1,z=0}\n  local candidates={support,{x=-support.x,z=-support.z},{x=-support.z,z=support.x},{x=support.z,z=-support.x}}\n  local cards={}\n  for _,d in ipairs(candidates)do\n   local q=point(-200+19.4*d.x,19.4*d.z,players[1].pos.y)\n   if s.mokoSafe(m,q.x,q.z,t)then cards[#cards+1]=d end\n  end\n  if #cards<2 then return nil end\n  local sources={};for id,target in pairs(m.tethers)do local tell=m.tells[id];if not tell or #tell<2 then return nil end;sources[#sources+1]={id=id,target=target,turn=tell[2]}end\n  if #sources~=4 then return nil end;table.sort(sources,function(a,b)return a.target<b.target end)\n  local playerByID={};for _,e in ipairs(players)do playerByID[e.id]=e end\n  local best,score\n  -- Four unique slots; the second tell determines which side can turn inward.\n  for i=1,#cards do for j=1,#cards do if i~=j then\n   local slots={};for _,d in ipairs({cards[i],cards[j]})do for _,sign in ipairs({-1,1})do\n    local tangent={x=-d.z,z=d.x};local face={x=sign*tangent.x,z=sign*tangent.z}\n    local q=point(-200+19.4*d.x+sign*4.7*tangent.x,19.4*d.z+sign*4.7*tangent.z,players[1].pos.y)\n    slots[#slots+1]={pos=q,face=heading(face),dir=d,sign=sign,tangent=tangent}\n   end end\n   local used,assignment={},{}\n   local function visit(k,cost)\n    if k==5 then\n     local origins={}\n     for _,v in pairs(assignment)do if type(v)=='table'and v.pos then origins[#origins+1]=point(v.pos.x-math.sin(v.face),v.pos.z-math.cos(v.face),v.pos.y)end end\n     -- Separation is a planning guard, not a claimed game collision threshold.\n     for a=1,#origins do for b=a+1,#origins do if dist(origins[a],origins[b])<7.4^2-.001 then return end end end\n     if not score or cost<score then best={};for id,v in pairs(assignment)do best[id]=v.pos;best['face:'..id]=v.face end;score=cost end;return\n    end\n    local v=sources[k];local e=playerByID[v.target];if not e then return end\n    for si,slot in ipairs(slots)do if not used[si]and s.mokoSafe(m,slot.pos.x,slot.pos.z,t)then\n     local inward=rotate({x=-math.sin(slot.face),z=-math.cos(slot.face)},v.turn)\n     if inward.x*(-slot.dir.x)+inward.z*(-slot.dir.z)>.6 then\n      local role=s.role(e);local preferred=role<=2 and support or cards[j]\n      local penalty=(slot.dir.x~=preferred.x or slot.dir.z~=preferred.z)and 100000 or 0\n      used[si]=true;assignment[v.target]=slot;visit(k+1,cost+penalty+dist(slot.pos,e.pos));assignment[v.target]=nil;used[si]=nil\n     end\n    end end\n   end\n   visit(1,0)\n  end end end\n  return best\n end\n function s.mokoNearestSafe(m,p,t,key,budgetAt)\n  if m.escapeKey~=key then m.escapeKey=key;m.escape=nil end\n  if m.escape and s.mokoSafe(m,m.escape.x,m.escape.z,t)then return m.escape end\n  m.escape=nil\n  local score;local budget=math.max(2,((budgetAt or t)-Now())/1000*5.5-1)\n  for x=-218,-182,.75 do for z=-18,18,.75 do if s.mokoSafe(m,x,z,t)then\n   local q=point(x,z,p.pos.y);local d=dist(q,p.pos)\n   if d<=budget^2 and(not score or d<score)then score=d;m.escape=q end\n  end end end\n  return m.escape\n end\n function s.mokoGuide(now,p)\n  if s.mokoUpwell(now,p)then return true end\n  local m=s.moko;if not m then return false end\n  if now>m.untilTime or math.abs(p.pos.x+200)>45 or math.abs(p.pos.z)>45 then\n   s.mokoDropFace(m);for _,c in pairs(m.clones)do s.remove(c.preview)end\n   for _,a in pairs(m.archers)do s.remove(a.uuid)end\n   s.moko=nil;if s.guide and s.guide.key:find('moko-',1,true)==1 then s.clearGuide()end;return false\n  end\n  local players={};for _,e in pairs(TensorCore.getEntityGroupList('Party'))do if e.alive then players[#players+1]=e end end\n  if #players~=4 then s.clearGuide();return true end\n  for _,a in pairs(m.hands)do\n   if jacobRokkonOptions.mokoBackups and now<a.deadline and not a.uuid then\n    a.uuid=s.own(s.red:addTimedCone(a.deadline-now,a.pos.x,a.pos.y,a.pos.z,a.r,a.angle,a.heading,0,false,true),a.deadline)\n   elseif a.uuid and(now>=a.deadline or not jacobRokkonOptions.mokoBackups)then s.remove(a.uuid);a.uuid=nil end\n  end\n  for _,a in pairs(m.archers)do\n   if a.forecast and now<a.deadline then\n    if not a.uuid then local q=a.pos;a.uuid=s.own(s.red:addTimedCircle(a.deadline-now,q.x,q.y,q.z,a.r,0,false,true),a.deadline);s.timer(a.deadline-now,q)end\n   end\n  end\n  if m.kind=='shadow'and not m.baitsDone and m.near~=nil then\n   local boss=TensorCore.mGetEntity(m.boss)\n   if boss then\n    table.sort(players,function(a,b)local da,db=dist(a.pos,boss.pos),dist(b.pos,boss.pos);return da==db and a.id<b.id or(m.near and da<db or not m.near and da>db)end)\n    m.baitDraws=m.baitDraws or{}\n    for i,e in ipairs(players)do\n     local u=m.baitDraws[e.id]\n     if i<=2 and m.baitAt and now<m.baitAt then\n      if u then s.red:updateTimedCircleOnEnt(u,m.baitAt-now,e.id,6,0,false,true);s.shapes[u]=m.baitAt\n      else m.baitDraws[e.id]=s.own(s.red:addTimedCircleOnEnt(m.baitAt-now,e.id,6,0,false,true),m.baitAt)end\n     elseif u then s.remove(u);m.baitDraws[e.id]=nil end\n    end\n   end\n  elseif m.baitDraws then for _,u in pairs(m.baitDraws)do s.remove(u)end;m.baitDraws=nil end\n  local count,done=0,0;local nextHit\n  for id,c in pairs(m.clones)do\n   count=count+1;if(c.hits or 0)>=2 then done=done+1 end\n   local a=s.mokoCone(m,id,c)\n   if a then\n    if not nextHit or a.deadline<nextHit then nextHit=a.deadline end\n    if not c.actual and a.deadline>now then\n     local sig=tostring(a.deadline)..':'..tostring(a.heading)\n     if c.previewKey~=sig then s.remove(c.preview);c.preview=s.own(s.red:addTimedCone(a.deadline-now,a.pos.x,a.pos.y,a.pos.z,a.r,a.angle,a.heading,0,false,true),a.deadline);c.previewKey=sig end\n    else s.remove(c.preview);c.preview=nil end\n   else s.remove(c.preview);c.preview=nil end\n  end\n  if m.lockedAt then\n   s.mokoDropFace(m)\n   if m.kind=='shadow'and not m.baitsDone then s.clearGuide();return true end\n   if m.kind~='scarlet'and count==(m.kind=='soldiers'and 4 or 2)and done==count then\n    if m.baitDraws then for _,u in pairs(m.baitDraws)do s.remove(u)end end\n    if not next(m.archers)then s.clearGuide();s.moko=nil;return false end\n    m.clonesDone=true\n   end\n   if m.clonesDone then\n    local t;for _,a in pairs(m.archers)do if a.deadline>now and(not t or a.deadline<t)then t=a.deadline end end\n    if t then\n     local q=s.mokoNearestSafe(m,p,t,'archer-repeat-'..m.revision)\n     if q then s.guideTo(q,t,'moko-archer-repeat')else s.clearGuide()end\n     s.mokoCall(m,'archer-repeat','Dodge the repeated archer blasts');return true\n    end\n   end\n   if not(m.kind=='soldiers'and jacobRokkonOptions.finalClones==1)and nextHit and nextHit>now-300 then\n    local checkAt=nextHit\n    if m.kind=='scarlet'then\n     for _,t in pairs(s.spreads)do if t>now and t<nextHit+1500 then checkAt=math.max(checkAt,t)end end\n     for _,t in pairs(s.stacks)do if t>now and t<nextHit+1500 then checkAt=math.max(checkAt,t)end end\n    end\n    local q=s.mokoNearestSafe(m,p,checkAt,tostring(m.revision)..':'..m.phase,nextHit)\n    if q then s.guideTo(q,nextHit,'moko-cleave-dodge')else s.clearGuide()end\n    if not q and m.kind=='soldiers'and m.phase==2 then s.mokoCall(m,'wait-arrows','Wait for the archer blasts before moving in')\n    else s.mokoCall(m,'dodge-'..m.phase,m.phase==1 and 'Jump locked: step into the green gap' or 'Dodge the second cleave')end\n    return true\n   end\n  end\n  local deadline;local spread=false\n  for _,t in pairs(s.spreads)do if t>now and(not deadline or t<deadline)then deadline=t;spread=true end end\n  for _,t in pairs(s.stacks)do if t>now and(not deadline or t<deadline)then deadline=t;spread=false end end\n  if m.kind=='scarlet'and m.spreadDone and m.stackDone then s.clearGuide();s.moko=nil;return false end\n  local t=deadline or m.jumpAt and m.jumpAt+600 or now+3000\n  local key=tostring(m.revision)..':'..tostring(deadline and math.floor(deadline/500))..':'..tostring(m.lockedAt)..':'..tostring(jacobRokkonOptions.finalClones)\n  if m.planAttempt~=key then\n   m.planAttempt=key;m.plan=nil\n   if m.kind=='scarlet'and deadline then m.plan=s.mokoScarletPlan(m,players,t,spread)\n   elseif m.kind=='shadow'and not m.lockedAt then m.plan=s.mokoShadowPlan(m,players)\n   elseif m.kind=='soldiers'and(not m.lockedAt or jacobRokkonOptions.finalClones==1)then\n    if jacobRokkonOptions.finalClones==2 then m.plan=s.mokoSoldierPlan(m,players,t)\n    else\n     m.plan={};for _,e in ipairs(players)do local role=s.role(e);local q=({{x=-200,z=-18},{x=-200,z=18},{x=-218,z=0},{x=-182,z=0}})[role];if q then m.plan[e.id]=point(q.x,q.z,e.pos.y)end end\n    end\n   end\n  end\n  local goal=m.plan and m.plan[p.id]\n  if goal and s.mokoSafe(m,goal.x,goal.z,t)then\n   local untilTime=m.lockedAt and m.untilTime or m.jumpAt or deadline or now+1000\n   s.guideTo(goal,untilTime,'moko-'..m.kind)\n   local face=m.plan['face:'..p.id]or(m.plan.tether==p.id and m.plan.face)\n   if face and not m.lockedAt and m.jumpAt then\n    if dist(goal,p.pos)<.64 then s.mokoFacing(m,p,face,m.jumpAt)else s.mokoDropFace(m)end\n    s.mokoCall(m,'bait-facing','Green spot, then face along the green facing arrow; hold for jump')\n   elseif m.kind=='shadow'then s.mokoCall(m,'bait-role-'..tostring(m.near),m.near and 'Untethered close; tethered far' or 'Untethered far; tethered close')\n   elseif m.kind=='soldiers'then s.mokoCall(m,'soldiers-'..jacobRokkonOptions.finalClones,jacobRokkonOptions.finalClones==1 and 'Your fixed-role spot' or 'Your kiss-pair spot')\n   else s.mokoCall(m,'scarlet-'..tostring(spread),spread and 'Your spread spot' or 'Your role partner')end\n  else\n   s.mokoDropFace(m);s.clearGuide()\n   if m.kind=='soldiers'and jacobRokkonOptions.finalClones==1 and m.jumpAt then s.mokoCall(m,'fixed-unsafe','Fixed-role spot is unsafe: dodge the archers')end\n  end\n  return true\n end\nend\n-- Optional native/Moogle alternatives remain authored but off by default.\nif s.mokoLateral then\n local a=s.mokoLateral\n if now>=a.deadline or not jacobRokkonOptions.mokoBackups then s.remove(a.uuid);s.mokoLateral=nil\n else\n  local e=TensorCore.mGetEntity(a.caster);local target=TensorCore.mGetEntity(a.target)\n  if e and target then\n   local h=TensorCore.getHeadingToTarget(e.pos,target.pos)\n   local sig=math.floor(h*100)..':'..math.floor(e.pos.x*10)..':'..math.floor(e.pos.z*10)\n   if a.sig~=sig then\n    s.remove(a.uuid);a.sig=sig\n    a.uuid=s.own(s.red:addTimedCone(a.deadline-now,e.pos.x,e.pos.y,e.pos.z,40,math.pi/2,h,0,false,true),a.deadline)\n   end\n  end\n end\nend\n\nif s.activeBossID then\n    local boss=TensorCore.mGetEntity(s.activeBossID)\n    if boss and not boss.alive then s.cleanup();s.activeBossID=nil;s.activeBoss=nil;self.used=true;return end\nend\nif s.statusReadUntil then\n    if now>s.statusReadUntil then s.statusReadUntil=nil;s.statusReadAt=nil\n    elseif now>=s.statusReadAt then\n        for _,e in pairs(TensorCore.getEntityGroupList(\"Party\")) do\n            for _,id in ipairs(s.statusIDs) do\n                local b=TensorCore.getBuff(e,id)\n                if b and b.duration>0 then\n                    local deadline=now+b.duration*1000\n                    if id==3563 or id==3608 or id==3610 then s.spreads[e.id]=deadline\n                    else s.stacks[e.id]=deadline;s.stackDeadline=deadline end\n                end\n            end\n        end\n        s.statusReadAt=now+250\n    end\nend\nif s.gOrderReadUntil then\n    if now>s.gOrderReadUntil or s.gOrangeOrder and s.gBlueOrder then s.gOrderReadUntil=nil\n    elseif now>=(s.gOrderReadAt or 0) then\n        for id=3597,3604 do\n            local b=TensorCore.getBuff(p,id)\n            if b and b.duration>0 then\n                if id<=3600 then s.gOrangeOrder=id-3596 else s.gBlueOrder=id-3600 end\n            end\n        end\n        for _,t in ipairs(s.gTowers or {}) do if not t.mine then s.gTower(t) end end\n        s.gOrderReadAt=now+250\n    end\nend\n-- Gorai-only controller; bounded by native mechanic setup and hit events.\nif s.goraiGuideVersion~=2 then\n s.goraiGuideVersion=2\n if s.g2 then s.g2.dropDest=nil end\n function s.goraiGuide(now,p)\n  if (p.pos.x-300)^2+(p.pos.z+120)^2>1600 then s.g2=nil;s.gLimit=nil;s.gExa=nil;return false end\n  local g=s.g2\n  if g and (now>g.untilTime or s.gTowerMode~=2) then s.g2=nil;s.clearGuide();g=nil end\n  if g and now>=(g.poll or 0) then\n   g.poll=now+250\n   local party={}\n   for _,e in pairs(TensorCore.getEntityGroupList(\"Party\")) do if e.alive then party[#party+1]=e end end\n   table.sort(party,function(a,b)return a.id<b.id end)\n   -- Both ordered colour sets must be present before assigning a destination.\n   for _,e in ipairs(party) do\n    local v=g.players[e.id] or {colors={}};g.players[e.id]=v\n    for wave=1,3 do\n     local blue=TensorCore.getBuff(e,3600+wave);local orange=TensorCore.getBuff(e,3596+wave)\n     local b=blue or orange\n     if b and b.duration>0 then v.colors[wave]=blue~=nil;v.deadlines=v.deadlines or {};v.deadlines[wave]=now+b.duration*1000 end\n    end\n    for _,id in ipairs({3605,3606}) do\n     local b=TensorCore.getBuff(e,id)\n     if b and b.duration>0 then v.dropBlue=id==3606;v.dropAt=now+b.duration*1000 end\n    end\n   end\n   -- Dropped wall towers are real event objects, not inferred player positions.\n   for _,def in ipairs({{2013333,false},{2013334,true}}) do\n    for _,e in pairs(TensorCore.entityList(\"contentid=\"..def[1])) do\n     if math.abs(e.pos.x-300)<21 and math.abs(e.pos.z+120)<21 then\n      local exists=false\n      for _,t in ipairs(g.towers)do if (t.pos.x-e.pos.x)^2+(t.pos.z-e.pos.z)^2<1 then exists=true end end\n      if not exists then g.towers[#g.towers+1]={pos={x=e.pos.x,y=e.pos.y,z=e.pos.z},blue=def[2],wave=3} end\n     end\n    end\n   end\n   local mine=g.players[p.id]\n   if not g.dropDest then\n    local used,plan={},{};local best,bestCost\n    local nw,ne,sw\n    for _,t in ipairs(g.towers)do if t.wave==1 then\n     if t.pos.x<300 and t.pos.z< -120 then nw=t.blue elseif t.pos.x>300 and t.pos.z< -120 then ne=t.blue elseif t.pos.x<300 and t.pos.z> -120 then sw=t.blue end\n    end end\n    local sides\n    if nw~=nil and ne~=nil and sw~=nil then\n     sides=nw==sw and {{-15,-5},{15,-5},{-15,5},{15,5}} or {{-5,-15},{5,-15},{-5,15},{5,15}}\n    else sides={} end\n    local function assignDrop(i,cost)\n     if i>#party then if not bestCost or cost<bestCost then bestCost=cost;best={};for id,q in pairs(plan)do best[id]=q end end;return end\n     local e=party[i];local v=g.players[e.id];if not v or v.colors[1]==nil then return end\n     for j,side in ipairs(sides)do if not used[j] then\n      local q={x=300+side[1],y=e.pos.y,z=-120+side[2]};local near=0;local valid=true\n      for _,t in ipairs(g.towers)do\n       local d=(q.x-t.pos.x)^2+(q.z-t.pos.z)^2\n       if d<64 then valid=false end\n       if t.wave<3 and t.blue~=v.colors[1] and d<=100.1 then near=near+1 end\n      end\n      for _,other in pairs(plan)do if (q.x-other.x)^2+(q.z-other.z)^2<64 then valid=false end end\n      if valid and near>=2 then used[j]=true;plan[e.id]=q;assignDrop(i+1,cost+(q.x-e.pos.x)^2+(q.z-e.pos.z)^2);used[j]=nil;plan[e.id]=nil end\n     end end\n    end\n    if #party==4 then assignDrop(1,0) end\n    if best then g.dropDest=best end\n   end\n   if mine and mine.dropAt and now<mine.dropAt then\n    local best=g.dropDest and g.dropDest[p.id]\n    if best then s.guideTo(best,mine.dropAt,\"gorai-drop\") end\n    if not g.dropCalled then g.dropCalled=true;s.call(\"Drop between opposite-colour towers\",false) end\n   elseif mine then\n    local wave=math.floor(g.hits/4)+1\n    if wave>3 then s.g2=nil;s.gTowerMode=nil;s.clearGuide();return false end\n    -- Match all four soakers jointly: minimum travel without duplicate assignments.\n    local towers={};for _,t in ipairs(g.towers)do if t.wave==wave and not t.resolved then towers[#towers+1]=t end end\n    local best,bestCost;local used,assignment={},{}\n    local function search(i,cost)\n     if i>#party then if not bestCost or cost<bestCost then bestCost=cost;best={};for k,t in pairs(assignment)do best[k]=t end end;return end\n     local e=party[i];local v=g.players[e.id];if not v or v.colors[wave]==nil then return end\n     for j,t in ipairs(towers)do if not used[j] and t.blue==v.colors[wave] then\n      local anchor=v.anchor or e.pos\n      local d=(anchor.x-t.pos.x)^2+(anchor.z-t.pos.z)^2\n      if wave==1 then\n       local continuation=false\n       for _,nextTower in ipairs(g.towers)do\n        if nextTower.wave==2 and nextTower.blue==v.colors[2] and (nextTower.pos.x-300)*(t.pos.x-300)>0 and (nextTower.pos.z+120)*(t.pos.z+120)>0 then\n         for _,last in ipairs(g.towers)do if last.wave==3 and last.blue==v.colors[3] and (last.pos.x-nextTower.pos.x)^2+(last.pos.z-nextTower.pos.z)^2<251 then continuation=true end end\n        end\n       end\n       if not continuation then d=d+100000 end\n      elseif wave==2 and v.anchor and ((v.anchor.x-300)*(t.pos.x-300)<0 or (v.anchor.z+120)*(t.pos.z+120)<0)then d=d+100000 end\n      if d<100000 then used[j]=true;assignment[e.id]=t;search(i+1,cost+d);used[j]=nil;assignment[e.id]=nil end\n     end end\n    end\n    if #party==4 and #towers==4 then search(1,0) end\n    if best and best[p.id] then\n     for id,t in pairs(best)do g.players[id].anchor=t.pos end\n     local t=best[p.id];local deadline=mine.deadlines and mine.deadlines[wave]\n     if deadline and deadline>now then\n      if g.marked~=t then\n       if g.mark then s.remove(g.mark) end\n       g.mark=s.own(s.green:addTimedCircle(deadline-now,t.pos.x,t.pos.y,t.pos.z,4,0,false,true),deadline)\n       s.timer(deadline-now,t.pos,0xFF33FF33);g.marked=t\n       s.call(({\"Middle tower\",\"Corner tower\",\"Wall tower: dodge the lines\"})[wave],false)\n      end\n      s.guideTo(t.pos,deadline,\"gorai-tower2-\"..wave)\n     end\n    end\n   end\n  end\n  if g then return true end\n  local lc=s.gLimit\n  if lc then\n   if now>lc.untilTime or lc.hits>=5 then s.gLimit=nil;s.clearGuide();return false end\n   if lc.number then\n    local n=lc.number;local slot=n\n    if n==4 and lc.hits<2 then slot=0 end\n    local points={{x=310,z=-130},{x=310,z=-110},{x=290,z=-130},{x=290,z=-110}}\n    local q\n    if lc.hits>=n then q=({{x=300,z=-135},{x=315,z=-120},{x=300,z=-135},{x=285,z=-120}})[n]\n    elseif slot==0 then q={x=285,z=-120}\n    else q=points[slot] end\n    s.guideTo({x=q.x,y=p.pos.y,z=q.z},lc.untilTime,\"gorai-limit-\"..n..\":\"..lc.hits)\n   end\n   return true\n  end\n  return false\n end\nend\n-- Show Gorai pair markers immediately after their buffs are known.\nif (p.pos.x-300)^2+(p.pos.z+120)^2<1600 then\n s.gEarlyPairs=s.gEarlyPairs or {}\n for id,deadline in pairs(s.stacks)do\n  if deadline>now and not s.gEarlyPairs[id] then\n   s.gEarlyPairs[id]=s.own(s.green:addTimedCircleOnEnt(deadline-now,id,s.stackRadius or 6,0,false,true),deadline)\n   AnyoneCore.addTimedWorldTextOnEnt(deadline-now,\"Pair stack\",id,0xFF33FF33,true,1.2,1.5)\n   local target=TensorCore.mGetEntity(id);if target then s.timer(deadline-now,target.pos,0xFF33FF33) end\n  end\n  if deadline>now then s.statusDrawn=s.statusDrawn or {};s.statusDrawn['pair:'..id..':'..math.floor(deadline/500)]=deadline end\n end\n for id,uuid in pairs(s.gEarlyPairs)do if not s.stacks[id] or s.stacks[id]<=now then s.remove(uuid);s.gEarlyPairs[id]=nil end end\nend\n\n\n-- Reuse My role for both Wails, including manual fake-melee assignments.\nif s.wailGuideVersion~=4 then\n s.wailGuideVersion=4\n function s.wailGuide(now,p)\n  local w=s.wail;if not w then return false end\n  if p.pos.x^2+(p.pos.z+100)^2>1600 then s.wail=nil;return false end\n  if now>w.untilTime then s.wail=nil;return false end\n  local spread=s.spreads[p.id];local stack\n  for _,t in pairs(s.stacks)do if t>now and (not stack or t<stack)then stack=t end end\n  local isSpread=spread and spread>now and (not stack or spread<stack)\n  local deadline=isSpread and spread or stack\n  if not deadline then return false end\n  local role=s.role();if not role then return false end\n  local boss=w.bossID and TensorCore.mGetEntity(w.bossID);if boss then w.heading=boss.pos.h end\n  local offsets=isSpread and {0,math.pi/2,-math.pi/2,math.pi} or (w.kind==2 and {math.pi/4,math.pi/4,-3*math.pi/4,-3*math.pi/4} or {math.pi/2,math.pi/2,-math.pi/2,-math.pi/2})\n  local h=w.heading+offsets[role]\n  if s.eye then\n   local v=s.eye;local out=v.advanced and not v.out or not v.advanced and v.out\n   local radius=out and 17 or 5.5\n   s.guideTo({x=v.pos.x+radius*math.sin(h),y=p.pos.y,z=v.pos.z+radius*math.cos(h)},deadline,\"wail-eye-\"..tostring(isSpread))\n   return true\n  end\n  -- First Wail: establish the next confirmed safe square, then face its layout toward the boss.\n  local wave=w.swipeWaves and w.swipeWaves[w.stage or 1]\n  if not wave or #wave.hazards<4 then s.clearGuide();return true end\n  local resolve=wave.deadline\n  local function safePoint(x,z)\n   for _,hazard in ipairs(wave.hazards)do if s.danger(hazard,x,z) then return false end end\n   return s.safe(x,z,resolve)\n  end\n  local bossPos=boss and boss.pos or {x=0,y=p.pos.y,z=-100}\n  local radius=isSpread and 5 or 4\n  local layoutKey=tostring(resolve)..\":\"..tostring(isSpread)..\":\"..tostring(s.circleArena)..\":\"..math.floor(bossPos.x*10)..\":\"..math.floor(bossPos.z*10)\n  w.layouts=w.layouts or {}\n  local cached=w.layouts[layoutKey]\n  if cached and cached[role] and safePoint(cached[role].x,cached[role].z) then\n   s.guideTo(cached[role],deadline,\"wail-ghoul-\"..tostring(isSpread));return true\n  end\n  local candidates,sumX,sumZ={},0,0\n  for x=-18,18 do for z=-118,-82 do\n   local face=TensorCore.getHeadingToTarget({x=x,y=p.pos.y,z=z},bossPos)\n   local valid=true\n   for r=1,4 do\n    local angle=face+offsets[r];local qx,qz=x+radius*math.sin(angle),z+radius*math.cos(angle)\n    local inside=s.circleArena and qx*qx+(qz+100)^2<=19^2 or not s.circleArena and math.abs(qx)<=19 and math.abs(qz+100)<=19\n    if not inside or not safePoint(qx,qz) then valid=false;break end\n   end\n   if valid then candidates[#candidates+1]={x=x,z=z,h=face};sumX=sumX+x;sumZ=sumZ+z end\n  end end\n  local best,score\n  if #candidates>0 then\n   sumX=sumX/#candidates;sumZ=sumZ/#candidates\n   for _,q in ipairs(candidates)do\n    local d=(q.x-sumX)^2+(q.z-sumZ)^2\n    if not score or d<score then score=d;best=q end\n   end\n  end\n  if best then\n   local goals={}\n   for r=1,4 do local angle=best.h+offsets[r];goals[r]={x=best.x+radius*math.sin(angle),y=p.pos.y,z=best.z+radius*math.cos(angle)} end\n   w.layouts[layoutKey]=goals\n   s.guideTo(goals[role],deadline,\"wail-ghoul-\"..tostring(isSpread))\n  else s.clearGuide() end\n  return true\n end\n -- Eye casts can ask for guidance before the next update; retain the same role solver.\n s.eyeSpot=function()local p=TensorCore.mGetPlayer();if p then s.wailGuide(Now(),p) end end\nend\n\n-- Cloud-only time-expanded route. Cache by actual cloud updates and the next resolution.\nif s.cloudRouteVersion~=1 then\n s.cloudRouteVersion=1\n function s.cloudRoute(firstTime)\n  local now=Now();local me=TensorCore.mGetPlayer();if not me then return end\n  local key=tostring(s.cloudRevision or 0)..':'..tostring(math.floor(firstTime))\n  local cache=s.cloudRouteCache\n  if cache and cache.key==key then\n   if cache.pos then s.guideTo(cache.pos,firstTime,'cloud-route-'..key) else s.clearGuide() end\n   return\n  end\n  local hs,times={},{}\n  for _,h in ipairs(s.hazards) do\n   if h.cloud and not h.cloudNoGuide and h.deadline>now and h.deadline<=firstTime+7000 then hs[#hs+1]=h;times[#times+1]=h.deadline end\n  end\n  table.sort(times)\n  local ts={}\n  for _,t in ipairs(times) do if #ts==0 or t-ts[#ts]>200 then ts[#ts+1]=t end end\n  while #ts>8 do table.remove(ts) end\n  local nodes,index={},{}\n  for x=-18,18 do for z=-18,18 do\n   if x*x+z*z<=18.5^2 then\n    local n={x=x,y=me.pos.y,z=z-100,gx=x,gz=z};nodes[#nodes+1]=n;index[(x+18)*37+z+19]=#nodes\n   end\n  end end\n  local costs={}\n  for k=#ts,1,-1 do\n   local cost={};costs[k]=cost\n   local relevant={}\n   for _,h in ipairs(hs) do if math.abs(h.deadline-ts[k])<=200 then relevant[#relevant+1]=h end end\n   local reach=k<#ts and math.max(0,(ts[k+1]-ts[k])/1000*5.5-0.4) or 0\n   local offsets={}\n   if k<#ts then\n    local n=math.floor(reach)\n    for dx=-n,n do for dz=-n,n do\n     local d2=dx*dx+dz*dz\n     if d2<=reach*reach then offsets[#offsets+1]={dx,dz,math.sqrt(d2)} end\n    end end\n   end\n   for id,q in ipairs(nodes) do\n    local safe=true\n    for _,h in ipairs(relevant) do if s.danger(h,q.x,q.z) then safe=false;break end end\n    if safe then\n     if k==#ts then cost[id]=0\n     else\n      local best,bid\n      for _,o in ipairs(offsets) do\n       local x,z=q.gx+o[1],q.gz+o[2]\n       if x>=-18 and x<=18 and z>=-18 and z<=18 then\n        local j=index[(x+18)*37+z+19];local rest=j and costs[k+1][j]\n        if rest then local value=rest+o[3];if not best or value<best then best=value;bid=j end end\n       end\n      end\n      cost[id]=best\n     end\n    end\n   end\n  end\n  local best,goal\n  if ts[1] then\n   local reach=math.max(0,(ts[1]-now)/1000*5.5-0.4)\n   for id,rest in pairs(costs[1]) do\n    local q=nodes[id];local d=math.sqrt((q.x-me.pos.x)^2+(q.z-me.pos.z)^2)\n    if d<=reach then local value=d+rest*1.1;if not best or value<best then best=value;goal=q end end\n   end\n  end\n  s.cloudRouteCache={key=key,pos=goal}\n  if goal then s.guideTo(goal,firstTime,'cloud-route-'..key) else s.clearGuide() end\n end\nend\n\n-- Only the next confirmed Rokujo resolution is rendered as danger.\nif s.cloudMode then\n local first\n for _,h in ipairs(s.hazards)do\n  if h.cloud and not h.cloudNoGuide and h.deadline>now and (not first or h.deadline<first)then first=h.deadline end\n end\n for _,h in ipairs(s.hazards)do\n  if h.cloud and not h.cloudNoGuide then\n   local show=first and h.deadline>now and h.deadline<=first+200\n   if not show and h.uuid then s.remove(h.uuid);h.uuid=nil\n   elseif show and not h.uuid then\n    local ms=h.deadline-now;local q=h.pos\n    if h.kind==\"circle\" then h.uuid=s.own(s.red:addTimedCircle(ms,q.x,q.y,q.z,h.r,0,false,true),h.deadline)\n    elseif h.kind==\"centered\" then h.uuid=s.own(s.red:addTimedCenteredRect(ms,q.x,q.y,q.z,h.length,h.width,h.heading,0,false,true),h.deadline)end\n   end\n  end\n end\nend\n\nif s.statusDrawVersion~=3 then\n s.statusDrawVersion=3\n s.statusDraws=function(now)\n        local localPlayer=TensorCore.mGetPlayer()\nif s.ghostPulseDraw then s.ghostPulseDraw(now) end\n        for id,deadline in pairs(s.spreads)do if deadline<=now then s.spreads[id]=nil end end\n        for id,deadline in pairs(s.stacks)do if deadline<=now then s.stacks[id]=nil end end\n        s.statusDrawn=s.statusDrawn or{}\n        for _,kind in ipairs({'spread','pair'})do\n            local entries=kind=='spread' and s.spreads or s.stacks\n            for id,deadline in pairs(entries)do\n                local e=TensorCore.mGetEntity(id)\n                local key=kind..':'..id..':'..math.floor(deadline/500)\n                if e and deadline-now<=4000 and not s.statusDrawn[key]then\n                    local ms=math.max(1,deadline-now)\n                    local radius=kind=='spread' and(s.spreadRadius or 6)or(s.stackRadius or 5)\n                    local drawer=kind=='spread' and s.red or s.green\n                    s.own(drawer:addTimedCircleOnEnt(ms,id,radius,0,false,true),deadline)\n                    AnyoneCore.addTimedWorldTextOnEnt(ms,kind=='spread' and 'Spread' or 'Pair stack',id,\n                        kind=='spread' and 0xFF3333FF or 0xFF33FF33,true,1.2,1.5)\n                    if jacobRokkonOptions.timers then\n                        if kind=='spread' then\n                            if localPlayer and id==localPlayer.id and RokkonWorldText then\n                                RokkonWorldText.addEntityCountdown(ms,id,0xFF3333FF,true,1.2,2.4,'rokkon-personal-spread')\n                            end\n                        else\n                            AnyoneCore.addWorldTextCountdown(ms,{x=e.pos.x,y=e.pos.y+2.4,z=e.pos.z},0xFF33FF33,true,1.2)\n                        end\n                    end\n                    s.statusDrawn[key]=deadline\n                end\n            end\n        end\n        for key,t in pairs(s.statusDrawn)do if t<=now then s.statusDrawn[key]=nil end end\n        local me=TensorCore.mGetPlayer();if not me then return end\n        local spread=s.spreads[me.id];local stack\n        for _,t in pairs(s.stacks)do if not stack or t<stack then stack=t end end\n        local deadline=spread and(not stack or spread<stack)and spread or stack\n        if not deadline then s.statusKey=nil;return end\n        local isSpread=deadline==spread\n        local key=tostring(math.floor(deadline/500))..(isSpread and ':spread' or ':pair')\n        if s.statusKey~=key then\n            s.statusKey=key;s.call(isSpread and 'Spread' or 'Pair stack',false)\n        end\n    end\nend\n\n-- Future ghoul waves remain available to planning but are not drawn as current danger.\nlocal nextSwipe\nfor _,hazard in ipairs(s.hazards)do if hazard.swipe and hazard.deadline>now and (not nextSwipe or hazard.deadline<nextSwipe)then nextSwipe=hazard.deadline end end\nfor _,hazard in ipairs(s.hazards)do if hazard.swipe then\n local show=nextSwipe and hazard.deadline>now and math.abs(hazard.deadline-nextSwipe)<250\n if not show and hazard.uuid then s.remove(hazard.uuid);hazard.uuid=nil\n elseif show and not hazard.uuid then local q=hazard.pos;hazard.uuid=s.own(s.red:addTimedCone(hazard.deadline-now,q.x,q.y,q.z,hazard.r,hazard.angle,hazard.heading,0,false,true),hazard.deadline) end\nend end\n\ns.statusDraws(now)\nif s.gazeUntil then\n    if now>=s.gazeUntil or not jacobRokkonOptions.gaze then\n        TensorCore.API.TensorACR.toggleLockFace(false)\n        TensorCore.API.TensorACR.setHardLockFace(false)\n        s.gazeUntil=nil\n    elseif now>=s.gazeAt then\n        local e=TensorCore.mGetEntity(s.gazeSource)\n        if e then\n            TensorCore.API.TensorACR.setLockFaceHeading((TensorCore.getHeadingToTarget(p.pos,e.pos)+math.pi)%(2*math.pi))\n            TensorCore.API.TensorACR.setHardLockFace(true)\n            TensorCore.API.TensorACR.toggleLockFace(true)\n        end\n    end\nend\nif s.towerGatherAt and now>=s.towerGatherAt and not s.towerAssigned and #s.towers==2 then\n    local marked,players=0,{}\n    for _,deadline in pairs(s.largeSpreads or {}) do if deadline>now then marked=marked+1 end end\n    if marked==2 then\n        for _,e in pairs(TensorCore.getEntityGroupList(\"Party\")) do\n            if e.alive and not (s.largeSpreads and s.largeSpreads[e.id] and s.largeSpreads[e.id]>now) then players[#players+1]=e end\n        end\n        if #players==2 then\n            table.sort(players,function(a,b)\n                local ar,br=s.role(a),s.role(b)\n                return ar==br and a.id<b.id or ar<br\n            end)\n            local a,b=s.towers[1],s.towers[2]\n            local function distance(e,t) return math.sqrt((e.pos.x-t.pos.x)^2+(e.pos.z-t.pos.z)^2) end\n            if jacobRokkonOptions.towerMode==1 then\n                if distance(players[1],b)+distance(players[2],a)<distance(players[1],a)+distance(players[2],b) then a,b=b,a end\n            elseif jacobRokkonOptions.towerMode==2 then\n                local center={x=0,y=0,z=-100}\n                local ah=(TensorCore.getHeadingToTarget(center,a.pos)+math.pi)%(2*math.pi)\n                local bh=(TensorCore.getHeadingToTarget(center,b.pos)+math.pi)%(2*math.pi)\n                if bh<ah then a,b=b,a end\n            end\n            if jacobRokkonOptions.towerMode~=3 then\n                s.towerAssigned=true\n                if players[1].id==p.id then s.myTower=a elseif players[2].id==p.id then s.myTower=b end\n                if s.myTower then\n                    local t=s.myTower\n                    s.own(s.green:addTimedCircle(t.deadline-now,t.pos.x,t.pos.y,t.pos.z,3.3,0,false,true),t.deadline)\n                    s.timer(t.deadline-now,t.pos,0xFF33FF33)\n                    s.call(\"Next: your green tower\",false)\n                end\n            else s.towerAssigned=true;s.call(\"Unmarked: soak a tower\",false) end\n        end\n    end\nend\nif s.towerGatherAt and s.towers[1] and now>=s.towers[1].deadline then\n    s.towerGatherAt=nil;s.myTower=nil;s.towers={};s.towerAssigned=nil;s.towerCalled=nil\nend\nfor u,deadline in pairs(s.shapes) do if now>=deadline then s.remove(u) end end\nfor i=#s.hazards,1,-1 do if now>=s.hazards[i].deadline then table.remove(s.hazards,i) end end\nif s.eye and now>=s.eye.first then\n    local v=s.eye\n    if not v.advanced then\n        v.advanced=true\n        s.clearGuide()\n        s.add({kind=v.out and \"donut\" or \"circle\",pos=v.pos,r=v.out and 30 or 15,inner=8,\n            deadline=v.second,caster=v.caster,spell=v.out and 33812 or 33814})\n        s.call(v.out and \"Move IN\" or \"Move OUT\",false)\n        s.eyeSpot()\n    end\n    if now>=v.second then s.eye=nil end\nend\nlocal forecastTime,forecastType\nif s.cloudGuideUntil or s.nobleGuideUntil then\n    for _,h in ipairs(s.hazards) do\n        if (h.cloud and s.cloudGuideUntil or h.noble and s.nobleGuideUntil) and h.deadline>now then\n            if not forecastTime or h.deadline<forecastTime then forecastTime=h.deadline;forecastType=h.cloud and \"cloud\" or \"noble\" end\n        end\n    end\n    if not forecastTime then s.cloudGuideUntil=nil;s.nobleGuideUntil=nil end\nend\nlocal exaTime\nif s.exaUntil and now<s.exaUntil then\n    for _,h in ipairs(s.hazards) do if h.exa and h.deadline>now and (not exaTime or h.deadline<exaTime) then exaTime=h.deadline end end\nelseif s.exaUntil then s.exaUntil=nil;s.exaCenter=nil;s.gExa=nil;s.g2=nil;s.gLimit=nil;s.gEarlyPairs=nil;s.swipeCallUntil=nil;s.cloudAnnounced=nil end\nif s.mokoGuide(now,p) then self.used=true;return\nelseif s.goraiGuide(now,p) then self.used=true;return\nelseif s.wailGuide(now,p) then self.used=true;return\nelseif s.ghostAwaitFinal and (s.ghostPulseCount or 0)<8 and s.ghostPhaseUntil and now<s.ghostPhaseUntil then s.clearGuide()\nelseif s.myGhost then\n    local e=TensorCore.mGetEntity(s.myGhost)\n    if e then\n        s.ghostLastSeen=now\n        if not s.ghostHeading then s.ghostHeading=(TensorCore.getHeadingToTarget({x=0,y=e.pos.y,z=-100},e.pos)+math.pi)%(2*math.pi) end\n        if not s.ghostRotate and e.pos.x^2+(e.pos.z+100)^2<25 then\n            s.ghostRotate=true;s.call(\"Rotate clockwise\",false)\n        end\n        local h=s.ghostHeading\n        if s.ghostRotate then h=TensorCore.getHeadingToTarget({x=0,y=p.pos.y,z=-100},p.pos)-math.pi/7 end\n        local x,z=18*math.sin(h),18*math.cos(h)\n        if not s.circleArena then\n            local scale=18/math.max(math.abs(x),math.abs(z))\n            x=x*scale;z=z*scale\n        end\n        s.guideTo({x=x,y=p.pos.y,z=-100+z},now+1000,\"ghost-kite\")\n    elseif s.ghostLastSeen and now-s.ghostLastSeen>1000 then s.myGhost=nil;s.clearGuide() end\nelseif s.hammerUntil and now<s.hammerUntil and s.hammerOrb then\n    if s.hammerTarget==p.id then s.guideTo(s.hammerOrb,s.hammerUntil,\"hammer-orb\")\n    else\n        local r=s.role()\n        local h=TensorCore.getHeadingToTarget(s.hammerOrb,{x=300,y=p.pos.y,z=-120})\n        if r==1 then h=h else h=h+math.pi/2 end\n        local d=r==1 and 5 or 7\n        s.guideTo({x=s.hammerOrb.x+d*math.sin(h),y=p.pos.y,z=s.hammerOrb.z+d*math.cos(h)},s.hammerUntil,\"hammer-avoid\")\n    end\nelseif s.flameUntil and now<s.flameUntil then\n    if s.guide and s.guide.key==\"flame\" and s.safe(s.guide.pos.x,s.guide.pos.z,s.flameUntil) then\n        s.guideTo(s.guide.pos,s.flameUntil,\"flame\")\n        self.used=true;return\n    end\n    local north=s.role()==1 or s.role()==2\n    local countN,countS=0,0\n    for _,e in pairs(TensorCore.getEntityGroupList(\"Party\")) do\n        if s.stacks[e.id] and s.stacks[e.id]>now then\n            local r=s.role(e)\n            if r==1 or r==2 then countN=countN+1 else countS=countS+1 end\n        end\n    end\n    if (countN==2 or countS==2) and (s.role()==2 or s.role()==3) then north=not north end\n    local best,score\n    for x=282,318,1 do\n        for z=north and -138 or -119,north and -121 or -102,1 do\n            if s.safe(x,z,s.flameUntil) then\n                local d=(x-p.pos.x)^2+(z-p.pos.z)^2\n                if not score or d<score then score=d;best={x=x,y=p.pos.y,z=z} end\n            end\n        end\n    end\n    if best then s.guideTo(best,s.flameUntil,\"flame\") end\nelseif s.defamationGuide(now,p) then\nelseif s.myTower and now<s.myTower.deadline and not s.myGhost then\n    if not s.towerCalled then s.towerCalled=true;s.call(\"Soak your tower\",false) end\n    s.guideTo(s.myTower.pos,s.myTower.deadline,\"personal-tower\")\nelseif forecastTime then\n    local stage=forecastType..math.floor(forecastTime/500)\n    if forecastType==\"cloud\" then s.cloudRoute(forecastTime) else s.nobleGuide(now,p,s.nobleGuideUntil) end\n    if s.cloudAnnounced~=forecastType and (forecastType~=\"noble\" or s.nobleGoal) then\n        s.cloudAnnounced=forecastType\n        s.cloudStage=stage;s.call(forecastType=='cloud' and 'Green gap, then follow the cleared space' or 'Dodge into the green gap',false)\n    end\nelseif s.triple and s.triple.deadline and now<s.triple.deadline then\n    local v=s.triple\n    local radius=v.inside and 3.5 or 8\n    local h=v.heading+math.pi\n    s.guideTo({x=v.pos.x+radius*math.sin(h),y=v.pos.y,z=v.pos.z+radius*math.cos(h)},v.deadline,\"triple-\"..v.index)\nelseif exaTime and s.exaCenter and s.exaCenter.x==300 and s.gExa then\n    local g=s.gExa;local role=s.role();local north=role==1 or role==2\n    local wave=g.waves or 0;local best,score\n    local stackTime;local markedNorth,markedSouth=0,0\n    for _,e in pairs(TensorCore.getEntityGroupList(\"Party\"))do\n        local deadline=s.stacks[e.id]\n        if deadline and deadline>now then\n            if not stackTime or deadline<stackTime then stackTime=deadline end\n            local r=s.role(e);if r==1 or r==2 then markedNorth=markedNorth+1 else markedSouth=markedSouth+1 end\n        end\n    end\n    if (wave>=3 or stackTime and stackTime<(s.spreads[p.id] or math.huge)) and (markedNorth==2 or markedSouth==2) and (role==2 or role==3)then north=not north end\n    for x=282,318 do for z=north and -138 or -119,north and -121 or -102 do\n        local wall=math.abs(x-300)>=17 or math.abs(z+120)>=17\n        local safe=s.safe(x,z,exaTime)\n        if wave<3 then\n            safe=safe and wall and s.safe(x,z,g.first+1100) and s.safe(x,z,g.first+2200)\n        end\n        if safe then\n            local d=(x-p.pos.x)^2+(z-p.pos.z)^2\n            if not score or d<score then score=d;best={x=x,y=p.pos.y,z=z} end\n        end\n    end end\n    if best then s.guideTo(best,exaTime,\"gorai-exa-\"..wave) else s.clearGuide() end\n    if g.called~=wave and (wave==0 or wave==3) then\n        g.called=wave;s.call(wave==0 and \"Start between exaflares; wait for three hits\" or \"Move into the cleared space\",false)\n    end\nelseif exaTime then s.avoid(exaTime,s.exaCenter,20,\"exa-\"..math.floor(exaTime/500))\nelseif s.eye then s.eyeSpot()\nelseif s.avoidUntil then\n    if now<s.avoidUntil then s.avoid(s.avoidUntil,s.avoidCenter,20,s.avoidKey)\n    else s.avoidUntil=nil;s.clearGuide() end\nelseif s.guide then\n    if now>=s.guide.deadline then s.clearGuide()\n    else s.guideTo(s.guide.pos,s.guide.deadline,s.guide.key) end\nend\nself.used=true\n",
						conditions = 
