				{
					data = 
					{
						aType = "Lua",
						actionLua = "-- Mount Rokkon: owned, pull-scoped draw state. Territory 1155 / 1156.\n-- Independent preferences shared by all Mount Rokkon reactions.\nif _G.RokkonSettingsFileReady~=2 then\n local folder=GetLuaModsPath()..[[TensorReactions\\Settings\\]]\n local path=folder..[[Mountrokkon.lua]]\n local defaults={role=1,towerMode=1,finalClones=1,enabled=true,arrows=true,timers=true,tts=true,gaze=true,fukoKB=true,goraiKB=true,triple=true,mokoBackups=false}\n local C=jacobRokkonOptions\n if not C then\n  C={}\n  if FileExists(path) then local saved=FileLoad(path);if type(saved)==\"table\" then C=saved end end\n end\n for key,value in pairs(defaults) do\n  if type(C[key])~=type(value) then C[key]=value end\n end\n C.role=math.max(1,math.min(5,math.floor(C.role)))\n C.towerMode=math.max(1,math.min(3,math.floor(C.towerMode)))\n C.finalClones=math.max(1,math.min(2,math.floor(C.finalClones)))\n function C.save()\n  if not FolderExists(folder) then FolderCreate(folder) end\n  local values={};for key in pairs(defaults) do values[key]=C[key] end\n  FileSave(path,values)\n end\n jacobRokkonOptions=C;C.save()\n _G.RokkonSettingsFileReady=2\nend\nif not data.jacobRokkon or data.jacobRokkon.version~=9 then\n    if data.jacobRokkon then data.jacobRokkon.cleanup() end\n    local s={version=9,hazards={},shapes={},steps={},spreads={},stacks={},towers={},circleArena=false}\n    data.jacobRokkon=s\n    s.red=TensorCore.getCachedDrawer(0x300000FF,nil,0x500000FF,0xFF0000FF,2)\n    s.green=TensorCore.getCachedDrawer(0x3000FF00,nil,0x5000FF00,0xFF00FF00,2)\n    function s.own(uuid,deadline)\n        if uuid then s.shapes[uuid]=deadline end\n        return uuid\n    end\n    function s.remove(uuid)\n        if uuid then Argus.deleteTimedShape(uuid); s.shapes[uuid]=nil end\n    end\n    function s.clearGuide()\n        s.remove(s.arrow);s.remove(s.destination);s.arrow=nil;s.destination=nil;s.guide=nil\n    end\n    function s.cleanup()\n        for u in pairs(s.shapes) do Argus.deleteTimedShape(u) end\n        if s.gazeUntil then\n            TensorCore.API.TensorACR.toggleLockFace(false)\n            TensorCore.API.TensorACR.setHardLockFace(false)\n        end\n        s.shapes={};s.hazards={};s.steps={};s.spreads={};s.stacks={};s.towers={}\n        s.arrow=nil;s.destination=nil;s.guide=nil;s.gazeUntil=nil;s.eye=nil;s.swipeUntil=nil\n        s.myTower=nil;s.myGhost=nil;s.towerGatherAt=nil;s.towerAssigned=nil;s.towerCalled=nil;s.largeSpreads={}\n        s.statusCircle=nil;s.statusKey=nil;s.statusDrawn={};s.ghostDanger={};s.rearPreview=nil\n        s.gTowerMode=nil;s.gTowers={};s.gMyTower=nil\n        s.triple=nil;s.moko=nil;s.mUpwell=nil;s.mokoLateral=nil\n        s.clouds={};s.cloudForecast={};s.noblePending={};s.cloudStage=nil;s.cloudMode=nil;s.cloudGuideUntil=nil;s.nobleGuideUntil=nil;s.charges={};s.rings={};s.noblePlan=nil;s.nobleGoal=nil;s.nobleSolved=nil;s.defamationGoals=nil;s.defamationCalled=nil;s.defamationAttempted=nil;s.breaths=0\n        s.exaUntil=nil;s.exaCenter=nil\n        s.flameUntil=nil;s.hammerUntil=nil;s.hammerOrb=nil;s.hammerTarget=nil\n        s.statusReadUntil=nil;s.statusReadAt=nil;s.gOrderReadUntil=nil\n    end\n    function s.role(ent)\n        local p=ent or TensorCore.mGetPlayer()\n        local r=jacobRokkonOptions.role\n        local me=TensorCore.mGetPlayer()\n        if r>1 and p and me and p.id==me.id then return r-1 end\n        if not p then return nil end\n        local j=p.job\n        if j==19 or j==21 or j==32 or j==37 then return 1 end\n        if j==24 or j==28 or j==33 or j==40 then return 2 end\n        local melee=j==20 or j==22 or j==30 or j==34 or j==39 or j==41\n        if r==4 and p.id~=me.id then return 4 end\n        if r==5 and p.id~=me.id then return 3 end\n        if melee then return 3 end\n        return 4\n    end\n    function s.call(text,red)\n        TensorCore.addAlertText(3000,text,1.2,red and 3 or 1,jacobRokkonOptions.tts,100)\n    end\n    function s.timer(ms,p,color)\n        if jacobRokkonOptions.timers then\n            AnyoneCore.addWorldTextCountdown(ms,{x=p.x,y=p.y+1,z=p.z},color or 0xFFFFFFFF,true,1.3)\n        end\n    end\n    function s.magicJob()\n        local p=TensorCore.mGetPlayer()\n        if not p then return false end\n        local j=p.job\n        return j==24 or j==25 or j==27 or j==28 or j==33 or j==35 or j==40 or j==42\n    end\n    function s.add(h)\n        h.start=h.start or Now();h.deadline=h.deadline or Now()+5000\n        local ms=math.max(1,h.deadline-Now())\n        local delay=(h.cloud or h.noble) and 0 or math.max(0,h.start-Now())\n        local p=h.pos\n        if h.noble then\n            local first=h.deadline\n            for _,v in ipairs(s.hazards)do if v.noble and v.deadline>Now() and v.deadline<first then first=v.deadline end end\n            if h.deadline>first+2500 then s.hazards[#s.hazards+1]=h;return h end\n        end\n        if h.kind==\"circle\" then h.uuid=s.own(s.red:addTimedCircle(ms,p.x,p.y,p.z,h.r,delay,false,true),h.deadline)\n        elseif h.kind==\"donut\" then h.uuid=s.own(s.red:addTimedDonut(ms,p.x,p.y,p.z,h.inner,h.r,delay,false,true),h.deadline)\n        elseif h.kind==\"cone\" then h.uuid=s.own(s.red:addTimedCone(ms,p.x,p.y,p.z,h.r,h.angle,h.heading,delay,false,true),h.deadline)\n        elseif h.kind==\"rect\" then h.uuid=s.own(s.red:addTimedRect(ms,p.x,p.y,p.z,h.length,h.width,h.heading,delay,false,true),h.deadline)\n        elseif h.kind==\"centered\" then h.uuid=s.own(s.red:addTimedCenteredRect(ms,p.x,p.y,p.z,h.length,h.width,h.heading,delay,false,true),h.deadline) end\n        s.hazards[#s.hazards+1]=h\n        if not h.noTimer then s.timer(ms,p) end\n        return h\n    end\n    function s.danger(h,x,z)\n        local dx,dz=x-h.pos.x,z-h.pos.z\n        local d2=dx*dx+dz*dz\n        if h.kind==\"circle\" then return d2<(h.r+0.6)^2 end\n        if h.kind==\"donut\" then return d2>(h.inner-0.6)^2 and d2<(h.r+0.6)^2 end\n        local along=dx*math.sin(h.heading)+dz*math.cos(h.heading)\n        if h.kind==\"cone\" then\n            return d2<(h.r+0.6)^2 and (d2<0.36 or along/math.sqrt(d2)>math.cos(h.angle/2+0.025))\n        end\n        local across=dx*math.cos(h.heading)-dz*math.sin(h.heading)\n        local low=h.kind==\"centered\" and -h.length/2 or 0\n        local high=h.kind==\"centered\" and h.length/2 or h.length\n        return along>low-0.6 and along<high+0.6 and math.abs(across)<h.width/2+0.6\n    end\n    function s.safe(x,z,deadline)\n        for _,h in ipairs(s.hazards) do\n            if h.start<=deadline and h.deadline>=deadline-400 and h.deadline<=deadline+800 and s.danger(h,x,z) then return false end\n        end\n        return true\n    end\n    function s.guideTo(pos,deadline,key)\n        if not jacobRokkonOptions.arrows then s.clearGuide();return end\n        local p=TensorCore.mGetPlayer()\n        if not p then return end\n        local ms=math.max(750,deadline-Now()+750)\n        s.guide={pos=pos,deadline=deadline,key=key}\n        if s.destination then\n            s.green:updateTimedCircle(s.destination,ms,pos.x,pos.y,pos.z,0.8,0,false,true)\n            s.shapes[s.destination]=deadline\n        else s.destination=s.own(s.green:addTimedCircle(ms,pos.x,pos.y,pos.z,0.8,0,false,true),deadline) end\n        local dist=math.sqrt((pos.x-p.pos.x)^2+(pos.z-p.pos.z)^2)\n        if dist<0.8 then s.remove(s.arrow);s.arrow=nil;return end\n        local heading=TensorCore.getHeadingToTarget(p.pos,pos)\n        if s.arrow then\n            s.green:updateTimedArrow(s.arrow,ms,p.pos.x,p.pos.y,p.pos.z,heading,math.max(0.1,dist-0.8),0.35,0.8,1.1,0,false)\n            s.shapes[s.arrow]=deadline\n        else s.arrow=s.own(s.green:addTimedArrow(ms,p.pos.x,p.pos.y,p.pos.z,heading,math.max(0.1,dist-0.8),0.35,0.8,1.1,0,false),deadline) end\n    end\n    function s.avoid(deadline,center,radius,key)\n        local p=TensorCore.mGetPlayer()\n        if not p then return end\n        local best,score=nil,math.huge\n        -- Keep an established safe destination until the next mechanic changes it.\n        if s.guide and s.guide.key==key and s.safe(s.guide.pos.x,s.guide.pos.z,deadline) then\n            s.guideTo(s.guide.pos,deadline,key);return\n        end\n        for x=center.x-radius+1,center.x+radius-1,1 do\n            for z=center.z-radius+1,center.z+radius-1,1 do\n                local arena=not (s.circleArena and center.x==0) or (x-center.x)^2+(z-center.z)^2<(radius-1)^2\n                if arena and s.safe(x,z,deadline) then\n                    local d=(x-p.pos.x)^2+(z-p.pos.z)^2\n                    if d<score then best,score={x=x,y=p.pos.y,z=z},d end\n                end\n            end\n        end\n        if best then s.guideTo(best,deadline,key) else s.clearGuide() end\n    end\n    function s.eyeSpot()\n        local v=s.eye\n        if not v then return end\n        local me=TensorCore.mGetPlayer()\n        if not me then return end\n        local role=s.role()\n        local out=v.advanced and not v.out or not v.advanced and v.out\n        local radius=out and 17 or 5.5\n        local now=Now()\n        local spread=s.spreads[me.id]\n        local spreadFirst=spread and spread>now and (not s.stackDeadline or spread<s.stackDeadline)\n        local north=role==1 or role==2\n        if not spreadFirst then\n            local countN,countS=0,0\n            for _,e in pairs(TensorCore.getEntityGroupList(\"Party\")) do\n                if s.stacks[e.id] and s.stacks[e.id]>now then\n                    local r=s.role(e)\n                    if r==1 or r==2 then countN=countN+1 else countS=countS+1 end\n                end\n            end\n            -- Healer / melee adjust when both stack markers are in the same role group.\n            if (countN==2 or countS==2) and (role==2 or role==3) then north=not north end\n        end\n        local dx,dz=0,north and -radius or radius\n        if spreadFirst then\n            dx=(role==1 or role==4) and radius/math.sqrt(2) or -radius/math.sqrt(2)\n            dz=north and -radius/math.sqrt(2) or radius/math.sqrt(2)\n        end\n        s.guideTo({x=v.pos.x+dx,y=me.pos.y,z=v.pos.z+dz},v.advanced and v.second or v.first,\"eye-personal\")\n    end\n    function s.statusDraws(now)\n        for id,deadline in pairs(s.spreads)do if deadline<=now then s.spreads[id]=nil end end\n        for id,deadline in pairs(s.stacks)do if deadline<=now then s.stacks[id]=nil end end\n        s.statusDrawn=s.statusDrawn or{}\n        for _,kind in ipairs({'spread','pair'})do\n            local entries=kind=='spread' and s.spreads or s.stacks\n            for id,deadline in pairs(entries)do\n                local e=TensorCore.mGetEntity(id)\n                local key=kind..':'..id..':'..math.floor(deadline/500)\n                if e and deadline-now<=4000 and not s.statusDrawn[key]then\n                    local ms=math.max(1,deadline-now)\n                    local radius=kind=='spread' and(s.spreadRadius or 6)or(s.stackRadius or 5)\n                    local drawer=kind=='spread' and s.red or s.green\n                    s.own(drawer:addTimedCircleOnEnt(ms,id,radius,0,false,true),deadline)\n                    AnyoneCore.addTimedWorldTextOnEnt(ms,kind=='spread' and 'Spread' or 'Pair stack',id,\n                        kind=='spread' and 0xFF3333FF or 0xFF33FF33,true,1.2,1.5)\n                    if jacobRokkonOptions.timers then\n                        AnyoneCore.addWorldTextCountdown(ms,{x=e.pos.x,y=e.pos.y+2.4,z=e.pos.z},\n                            kind=='spread' and 0xFF3333FF or 0xFF33FF33,true,1.2)\n                    end\n                    s.statusDrawn[key]=deadline\n                end\n            end\n        end\n        for key,t in pairs(s.statusDrawn)do if t<=now then s.statusDrawn[key]=nil end end\n        local me=TensorCore.mGetPlayer();if not me then return end\n        local spread=s.spreads[me.id];local stack\n        for _,t in pairs(s.stacks)do if not stack or t<stack then stack=t end end\n        local deadline=spread and(not stack or spread<stack)and spread or stack\n        if not deadline then s.statusKey=nil;return end\n        local isSpread=deadline==spread\n        local key=tostring(math.floor(deadline/500))..(isSpread and ':spread' or ':pair')\n        if s.statusKey~=key then\n            s.statusKey=key;s.call(isSpread and 'Spread' or 'Pair stack',false)\n        end\n    end\nend\n\nlocal s=data.jacobRokkon\nif not s.spec then s.spec={[33820]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Avoid the rear cleave\",[\"r\"]=25,[\"angle\"]=1.5707963267948966},[33859]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Avoid the rear cleave\",[\"r\"]=25,[\"angle\"]=1.5707963267948966},[33795]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"r\"]=6},[33834]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"r\"]=6},[33796]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=2},[33835]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=2},[33797]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=6},[33836]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=6},[33798]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=12},[33837]={[\"kind\"]=\"rect\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=nil,[\"length\"]=100,[\"width\"]=12},[33803]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Dodge the swipes\",[\"r\"]=40,[\"angle\"]=3.141592653589793},[33804]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Dodge the swipes\",[\"r\"]=40,[\"angle\"]=3.141592653589793},[33842]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=0,[\"z\"]=-100},[\"call\"]=\"Dodge the swipes\"