					{
						aType = "Lua",
						actionLua = "-- Reusable entity-following countdown; identical installer may exist in multiple profiles.\n-- RenderManager:WorldToScreen documented at wiki.mmominion.com/doku.php?id=gui_api.\nif not RokkonWorldText or (RokkonWorldText.version or 0)<1 then\n local H={version=1,entries={},serial=0}\n RokkonWorldText=H\n function H.addEntityCountdown(timeoutMs,entityID,color,background,sizeMultiplier,heightAddition,key)\n  local e=TensorCore.mGetEntity(entityID)\n  local p=TensorCore.mGetPlayer()\n  if not e or not e.pos or timeoutMs<=0 then return nil end\n  if key and H.entries[key] and H.entries[key].deadline>Now() then return key end\n  H.serial=H.serial+1;key=key or ('entity-countdown-'..H.serial)\n  H.entries[key]={entityID=entityID,deadline=Now()+timeoutMs,color=color or 0xFFFFFFFF,background=background~=false,scale=sizeMultiplier or 1,height=heightAddition or 1,map=p and p.localmapid}\n  return key\n end\n function H.cancelEntityCountdown(key) H.entries[key]=nil end\nend\nlocal H=RokkonWorldText\nlocal frame=GUI:GetFrameCount()\nif H.lastFrame==frame then self.used=true return end\nH.lastFrame=frame\nif not next(H.entries) then self.used=true return end\nlocal now=Now();local p=TensorCore.mGetPlayer()\nif not p or (p.localmapid~=1155 and p.localmapid~=1156) or not jacobRokkonOptions or not jacobRokkonOptions.enabled then H.entries={};self.used=true;return end\nlocal active={}\nfor key,entry in pairs(H.entries) do\n local e=TensorCore.mGetEntity(entry.entityID)\n if now>=entry.deadline or not p or p.localmapid~=entry.map or not e or not e.pos or not e.alive then H.entries[key]=nil\n else active[#active+1]={entry=entry,entity=e} end\nend\nif #active==0 then self.used=true return end\nlocal width,height=GUI:GetScreenSize()\nGUI:SetNextWindowPos(0,0,GUI.SetCond_Always)\nGUI:SetNextWindowSize(width,height,GUI.SetCond_Always)\nGUI:PushStyleColor(GUI.Col_WindowBg,0,0,0,0)\nlocal flags=GUI.WindowFlags_NoTitleBar+GUI.WindowFlags_NoResize+GUI.WindowFlags_NoMove+GUI.WindowFlags_NoScrollbar+GUI.WindowFlags_NoSavedSettings+GUI.WindowFlags_NoInputs+GUI.WindowFlags_NoFocusOnAppearing\nlocal visible=GUI:Begin('##RokkonEntityCountdownOverlay',true,flags)\nif visible then\n for _,item in ipairs(active) do\n  local entry,e=item.entry,item.entity\n  local x,y=RenderManager:WorldToScreen({x=e.pos.x,y=e.pos.y+entry.height,z=e.pos.z},true)\n  if x and y then\n   GUI:SetWindowFontScale(entry.scale)\n   local text=string.format('%.1f',math.max(0,(entry.deadline-now)/1000))\n   local w,h=GUI:CalcTextSize(text)\n   x,y=x-w/2,y-h/2\n   if entry.background then GUI:AddRectFilled(x-4,y-2,x+w+4,y+h+2,0xA0000000,4) end\n   GUI:AddText(x,y,entry.color,text)\n  end\n end\n GUI:SetWindowFontScale(1)\nend\nGUI:End();GUI:PopStyleColor()\nself.used=true\n",
