469},[34246]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=60,[\"angle\"]=4.71238898038469},[34294]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=60,[\"angle\"]=4.71238898038469},[34295]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=60,[\"angle\"]=4.71238898038469},[34296]={[\"kind\"]=\"cone\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=60,[\"angle\"]=4.71238898038469},[34255]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=10},[34302]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=10},[34727]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=10},[34729]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=10},[34256]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=20},[34303]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=20},[34728]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=20},[34730]={[\"kind\"]=\"circle\",[\"arena\"]={[\"x\"]=-200,[\"z\"]=0},[\"call\"]=nil,[\"r\"]=20},[34390]={[\"kind\"]=\"circle\",[\"arena\"]=nil,[\"call\"]=\"Move OUT\",[\"r\"]=10},[34408]={[\"kind\"]=\"circle\",[\"arena\"]=nil,[\"call\"]=\"Move OUT\",[\"r\"]=10},[34394]={[\"kind\"]=\"circle\",[\"arena\"]=nil,[\"call\"]=\"Move OUT\",[\"r\"]=10},[34412]={[\"kind\"]=\"circle\",[\"arena\"]=nil,[\"call\"]=\"Move OUT\",[\"r\"]=10},[34389]={[\"kind\"]=\"donut\",[\"arena\"]=nil,[\"call\"]=\"Move IN\",[\"inner\"]=5,[\"r\"]=30},[34407]={[\"kind\"]=\"donut\",[\"arena\"]=nil,[\"call\"]=\"Move IN\",[\"inner\"]=5,[\"r\"]=30},[34391]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=nil,[\"r\"]=12,[\"angle\"]=2.0943951023931953},[34409]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=nil,[\"r\"]=12,[\"angle\"]=2.0943951023931953},[34437]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34438]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34440]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34441]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34404]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34429]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34422]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34430]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34439]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=8},[34442]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=8}} end\nlocal s=data.jacobRokkon\nif not s.goraiHelpers then\n    s.goraiHelpers=true\n    function s.gTower(t)\n        local p=TensorCore.mGetPlayer()\n        if not p or not s.gTowerMode or s.gTowerMode~=1 then return end\n        local blue=t.index%2==0\n        local order=blue and s.gBlueOrder or s.gOrangeOrder\n        if order~=t.wave then return end\n        t.mine=true\n        s.own(s.green:addTimedCircle(t.deadline-Now(),t.pos.x,t.pos.y,t.pos.z,3.3,0,false,true),t.deadline)\n        s.timer(t.deadline-Now(),t.pos,0xFF33FF33)\n        if not s.gMyTower or t.wave<s.gMyTower.wave then s.gMyTower=t end\n        s.call((t.wave>s.gResolvedWave+1 and \"Next: \" or \"\")..(blue and \"Blue tower\" or \"Orange tower\"),false)\n        if s.gMyTower==t then s.guideTo(t.pos,t.deadline,\"gorai-tower-\"..t.wave) end\n    end\nend\n\nlocal s=data.jacobRokkon\nif not s.mokoHelpers then\n    s.mokoHelpers=true\n    function s.tripleStep(v,pos,heading,inside,deadline)\n        if v.shapes then for _,u in ipairs(v.shapes) do s.remove(u) end end\n        v.pos=pos;v.heading=heading;v.deadline=deadline;v.inside=inside\n        local cone=s.add({kind=\"cone\",pos=pos,r=60,angle=math.pi*1.5,heading=heading,deadline=deadline,caster=v.boss,noTimer=true})\n        local radial=s.add({kind=inside and \"donut\" or \"circle\",pos=pos,inner=6,r=inside and 40 or 6,deadline=deadline,caster=v.boss,noTimer=true})\n        v.shapes={cone.uuid,radial.uuid}\n        s.timer(math.max(1,deadline-Now()),pos)\n        local h=heading+math.pi\n        local r=inside and 3.5 or 8\n        s.clearGuide()\n        s.guideTo({x=pos.x+r*math.sin(h),y=pos.y,z=pos.z+r*math.cos(h)},deadline,\"triple-\"..v.index)\n        if v.called~=v.index then s.call((inside and \"IN\" or \"OUT\")..\": green wedge\",false);v.called=v.index end\n    end\nend\n\nlocal s=data.jacobRokkon\n-- Release only Rokkon-owned mechanic state when the replay clock discontinuously seeks.\nlocal clock=TensorReactions_CurrentCombatTimer\nlocal tick=Now()\nlocal seek=s.clockGuardVersion~=1 or (s.lastCombatClock and (clock<s.lastCombatClock-0.5 or (clock>s.lastCombatClock+5 and tick-(s.lastClockTick or tick)<1000)))\nif seek then\n s.cleanup()\n s.wail=nil;s.g2=nil;s.gLimit=nil;s.gExa=nil;s.gEarlyPairs=nil\n s.cloudRouteCache=nil;s.cloudRevision=(s.cloudRevision or 0)+1\n s.swipeCallUntil=nil;s.cloudAnnounced=nil\n if RokkonWorldText then RokkonWorldText.entries={} end\n s.clockGuardVersion=1\nend\ns.lastCombatClock=clock;s.lastClockTick=tick\n\nif not s.shishioHelpers then\n    s.shishioHelpers=true;s.clouds={};s.cloudForecast={};s.breaths=0;s.rings={}\n    function s.cloudChain(line)\n        local radius=({8,12,23})[s.breaths]\n        if not radius then return end\n        local times={}\n        for id,c in pairs(s.clouds) do\n            local dx,dz=c.pos.x-line.pos.x,c.pos.z-line.pos.z\n            local along=dx*math.sin(line.heading)+dz*math.cos(line.heading)\n            local across=dx*math.cos(line.heading)-dz*math.sin(line.heading)\n            if math.abs(along)<=30 and math.abs(across)<=7 then times[id]=line.deadline+1100 end\n        end\n        for _=1,32 do\n            local changed=false\n            for id,c in pairs(s.clouds) do\n                if times[id] then\n                    for other,d in pairs(s.clouds) do\n                        if other~=id and (c.pos.x-d.pos.x)^2+(c.pos.z-d.pos.z)^2<=radius^2 then\n                            local t=times[id]+1100\n                            if not times[other] or t<times[other] then times[other]=t;changed=true end\n                        end\n                    end\n                end\n            end\n            if not changed then break end\n        end\n        for id,deadline in pairs(times) do\n            local old=s.cloudForecast[id]\n            if not old or deadline<old.deadline then\n                if old then s.remove(old.uuid);old.deadline=0 end\n                local c=s.clouds[id]\n                local h=s.add({kind=\"circle\",pos=c.pos,r=radius,start=deadline-1100,deadline=deadline,\n                    caster=id,cloud=true,noTimer=true})\n                s.cloudForecast[id]=h\n            end\n        end\n    end\n    function s.nobleRing(pos,h)\n        s.rings=s.rings or {}\n        local seen=false\n        for _,q in ipairs(s.rings)do if (q.x-pos.x)^2+(q.z-pos.z)^2<.01 then seen=true;break end end\n        local last=s.charges and s.charges[#s.charges]\n        if not last then\n            s.noblePending=s.noblePending or{};s.noblePending[#s.noblePending+1]={pos=pos,heading=h};return\n        end\n        if not s.danger(last,pos.x,pos.z) then\n            local from=s.nobleEnd\n            local dx,dz=pos.x-from.x,pos.z-from.z\n            if math.abs(dx)<.1 then dx=0 end\n            if math.abs(dz)<.1 then dz=0 end\n            local len=math.sqrt(dx*dx+dz*dz)\n            if len<.1 then return end\n            local ux,uz=dx/len,dz/len\n            local tx=math.abs(ux)>.001 and ((ux>0 and 20 or -20)-from.x)/ux or math.huge\n            local tz=math.abs(uz)>.001 and ((uz>0 and -80 or -120)-from.z)/uz or math.huge\n            local length=math.min(tx,tz)\n            if length<=0 or length>60 then return end\n            last=s.add({kind=\"rect\",pos=from,length=length,width=12,heading=TensorCore.getHeadingToTarget(from,pos),\n                start=last.deadline,deadline=last.deadline+1400,noTimer=true,noble=true})\n            s.charges[#s.charges+1]=last\n            s.nobleEnd={x=from.x+ux*length,y=from.y,z=from.z+uz*length}\n        end\n        s.add({kind=\"centered\",pos=pos,length=10,width=100,heading=h,start=last.deadline,\n            deadline=last.deadline+800,noTimer=true,noble=true})\n        if not seen then s.rings[#s.rings+1]=pos end\n        s.noblePlan=nil;s.nobleGoal=nil;s.nobleSolved=nil\n    end\nend\n\nlocal o=jacobRokkonOptions\nlocal visible=GUI:Begin(\"Mount Rokkon draws\")\nif visible then\n    local changed=false\n    local v,c=GUI:Checkbox(\"Enable draws\",o.enabled);o.enabled=v;changed=changed or c\n    GUI:Text(\"Green = safe position. Red = incoming attack.\")\n    local r=GUI:Combo(\"My role\",o.role,{\"Automatic (job)\",\"Tank\",\"Healer\",\"Melee\",\"Ranged\"})\n    if r~=o.role then o.role=r;changed=true end\n    if GUI:CollapsingHeader(\"Shishio\") then\n        local t=GUI:Combo(\"Unmarked tower assignment\",o.towerMode,{\"Shortest combined travel (lock once)\",\"Role priority: Tank, Healer, Melee, Ranged\",\"Manual: callout only\"})\n        if t~=o.towerMode then o.towerMode=t;changed=true end\n        GUI:Text(\"Only unmarked players soak. Coordinate this choice with your group.\")\n        GUI:Text(\"The guide does not prescribe a tower-selection priority.\")\n    end\n    if GUI:CollapsingHeader(\"Trash: gaze and knockback\") then\n        v,c=GUI:Checkbox(\"Gaze of the Tengu: automatic look away\",o.gaze);o.gaze=v;changed=changed or c\n        v,c=GUI:Checkbox(\"Fuko Crosswind: request knockback immunity\",o.fukoKB);o.fukoKB=v;changed=changed or c\n        GUI:Text(\"Immunity has a 120s cooldown. Later Crosswinds may need to be ridden.\")\n    end\n    if GUI:CollapsingHeader(\"Gorai\") then\n        v,c=GUI:Checkbox(\"Fighting Spirits: request knockback immunity\",o.goraiKB);o.goraiKB=v;changed=changed or c\n        GUI:Text(\"Preposition at your number when using immunity.\")\n    end\n    if GUI:CollapsingHeader(\"Moko\") then\n        v,c=GUI:Checkbox(\"Moogle fallback draws (off by default)\",o.mokoBackups);o.mokoBackups=v;changed=changed or c\n        GUI:Text(\"Backup Azure centre, tankbuster and hand cones. Enable if Moogle misses them.\")\n        v,c=GUI:Checkbox(\"Triple Kasumi-giri: step-by-step green wedge\",o.triple);o.triple=v;changed=changed or c\n        local mode=GUI:Combo(\"Final clone strategy\",o.finalClones,{\"Raidplan: fixed roles (default)\",\"Video: tether-based\"})\n        if mode~=o.finalClones then o.finalClones=mode;changed=true end\n        if o.finalClones==1 then\n            GUI:Text(\"Tank N / Healer S / Melee W / Ranged E.\")\n            GUI:Text(\"Accepts Damage Down; ignore clone tethers for the fixed spread.\")\n        else\n            GUI:Text(\"Kiss pairs: safe archer sides, facing arrow, then dodge both cleaves.\")\n        end\n        GUI:Text(\"Fixed roles keep your saved strategy; tether-based enables the kiss solver.\")\n    end\n    for _,row in ipairs({{\"arrows\",\"Personal movement arrows\"},{\"timers\",\"Continuous countdowns\"},{\"tts\",\"Spoken callouts\"}}) do\n        v,c=GUI:Checkbox(row[2],o[row[1]]);o[row[1]]=v;changed=changed or c\n    end\n    GUI:Text(\"Criterion 1155 / Savage 1156\")\n    if changed then o.save() end\nend\nGUI:End()\nself.used=true\n",
