=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34438]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34440]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34441]={[\"kind\"]=\"cone\",[\"arena\"]=nil,[\"call\"]=\"Dodge the swipe\",[\"r\"]=60,[\"angle\"]=3.141592653589793},[34404]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34429]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34422]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34430]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=3},[34439]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=8},[34442]={[\"kind\"]=\"rect\",[\"arena\"]=nil,[\"call\"]=nil,[\"length\"]=40,[\"width\"]=8}} end\nlocal s=data.jacobRokkon\nif not s.goraiHelpers then\n    s.goraiHelpers=true\n    function s.gTower(t)\n        local p=TensorCore.mGetPlayer()\n        if not p or not s.gTowerMode or s.gTowerMode~=1 then return end\n        local blue=t.index%2==0\n        local order=blue and s.gBlueOrder or s.gOrangeOrder\n        if order~=t.wave then return end\n        t.mine=true\n        s.own(s.green:addTimedCircle(t.deadline-Now(),t.pos.x,t.pos.y,t.pos.z,3.3,0,false,true),t.deadline)\n        s.timer(t.deadline-Now(),t.pos,0xFF33FF33)\n        if not s.gMyTower or t.wave<s.gMyTower.wave then s.gMyTower=t end\n        s.call((t.wave>s.gResolvedWave+1 and \"Next: \" or \"\")..(blue and \"Blue tower\" or \"Orange tower\"),false)\n        if s.gMyTower==t then s.guideTo(t.pos,t.deadline,\"gorai-tower-\"..t.wave) end\n    end\nend\n\nlocal s=data.jacobRokkon\nif not s.mokoHelpers then\n    s.mokoHelpers=true\n    function s.tripleStep(v,pos,heading,inside,deadline)\n        if v.shapes then for _,u in ipairs(v.shapes) do s.remove(u) end end\n        v.pos=pos;v.heading=heading;v.deadline=deadline;v.inside=inside\n        local cone=s.add({kind=\"cone\",pos=pos,r=60,angle=math.pi*1.5,heading=heading,deadline=deadline,caster=v.boss,noTimer=true})\n        local radial=s.add({kind=inside and \"donut\" or \"circle\",pos=pos,inner=6,r=inside and 40 or 6,deadline=deadline,caster=v.boss,noTimer=true})\n        v.shapes={cone.uuid,radial.uuid}\n        s.timer(math.max(1,deadline-Now()),pos)\n        local h=heading+math.pi\n        local r=inside and 3.5 or 8\n        s.clearGuide()\n        s.guideTo({x=pos.x+r*math.sin(h),y=pos.y,z=pos.z+r*math.cos(h)},deadline,\"triple-\"..v.index)\n        if v.called~=v.index then s.call((inside and \"IN\" or \"OUT\")..\": green wedge\",false);v.called=v.index end\n    end\nend\n\nlocal s=data.jacobRokkon\nif not s.shishioHelpers then\n    s.shishioHelpers=true;s.clouds={};s.cloudForecast={};s.breaths=0;s.rings={}\n    function s.cloudChain(line)\n        local radius=({8,12,23})[s.breaths]\n        if not radius then return end\n        local times={}\n        for id,c in pairs(s.clouds) do\n            local dx,dz=c.pos.x-line.pos.x,c.pos.z-line.pos.z\n            local along=dx*math.sin(line.heading)+dz*math.cos(line.heading)\n            local across=dx*math.cos(line.heading)-dz*math.sin(line.heading)\n            if math.abs(along)<=30 and math.abs(across)<=7 then times[id]=line.deadline+1100 end\n        end\n        for _=1,32 do\n            local changed=false\n            for id,c in pairs(s.clouds) do\n                if times[id] then\n                    for other,d in pairs(s.clouds) do\n                        if other~=id and (c.pos.x-d.pos.x)^2+(c.pos.z-d.pos.z)^2<=radius^2 then\n                            local t=times[id]+1100\n                            if not times[other] or t<times[other] then times[other]=t;changed=true end\n                        end\n                    end\n                end\n            end\n            if not changed then break end\n        end\n        for id,deadline in pairs(times) do\n            local old=s.cloudForecast[id]\n            if not old or deadline<old.deadline then\n                if old then s.remove(old.uuid);old.deadline=0 end\n                local c=s.clouds[id]\n                local h=s.add({kind=\"circle\",pos=c.pos,r=radius,start=deadline-1100,deadline=deadline,\n                    caster=id,cloud=true,noTimer=true})\n                s.cloudForecast[id]=h\n            end\n        end\n    end\n    function s.nobleRing(pos,h)\n        s.rings=s.rings or {}\n        local seen=false\n        for _,q in ipairs(s.rings)do if (q.x-pos.x)^2+(q.z-pos.z)^2<.01 then seen=true;break end end\n        local last=s.charges and s.charges[#s.charges]\n        if not last then\n            s.noblePending=s.noblePending or{};s.noblePending[#s.noblePending+1]={pos=pos,heading=h};return\n        end\n        if not s.danger(last,pos.x,pos.z) then\n            local from=s.nobleEnd\n            local dx,dz=pos.x-from.x,pos.z-from.z\n            if math.abs(dx)<.1 then dx=0 end\n            if math.abs(dz)<.1 then dz=0 end\n            local len=math.sqrt(dx*dx+dz*dz)\n            if len<.1 then return end\n            local ux,uz=dx/len,dz/len\n            local tx=math.abs(ux)>.001 and ((ux>0 and 20 or -20)-from.x)/ux or math.huge\n            local tz=math.abs(uz)>.001 and ((uz>0 and -80 or -120)-from.z)/uz or math.huge\n            local length=math.min(tx,tz)\n            if length<=0 or length>60 then return end\n            last=s.add({kind=\"rect\",pos=from,length=length,width=12,heading=TensorCore.getHeadingToTarget(from,pos),\n                start=last.deadline,deadline=last.deadline+1400,noTimer=true,noble=true})\n            s.charges[#s.charges+1]=last\n            s.nobleEnd={x=from.x+ux*length,y=from.y,z=from.z+uz*length}\n        end\n        s.add({kind=\"centered\",pos=pos,length=10,width=100,heading=h,start=last.deadline,\n            deadline=last.deadline+800,noTimer=true,noble=true})\n        if not seen then s.rings[#s.rings+1]=pos end\n        s.noblePlan=nil;s.nobleGoal=nil;s.nobleSolved=nil\n    end\nend\n\nlocal me=TensorCore.mGetPlayer()\nif not me then return end\nlocal s=data.jacobRokkon\n-- Release only Rokkon-owned mechanic state when the replay clock discontinuously seeks.\nlocal clock=TensorReactions_CurrentCombatTimer\nlocal tick=Now()\nlocal seek=s.clockGuardVersion~=1 or (s.lastCombatClock and (clock<s.lastCombatClock-0.5 or (clock>s.lastCombatClock+5 and tick-(s.lastClockTick or tick)<1000)))\nif seek then\n s.cleanup()\n s.wail=nil;s.g2=nil;s.gLimit=nil;s.gExa=nil;s.gEarlyPairs=nil\n s.cloudRouteCache=nil;s.cloudRevision=(s.cloudRevision or 0)+1\n s.swipeCallUntil=nil;s.cloudAnnounced=nil\n if RokkonWorldText then RokkonWorldText.entries={} end\n s.clockGuardVersion=1\nend\ns.lastCombatClock=clock;s.lastClockTick=tick\nlocal MOKO_EVENT='channel'\n-- Event-specific branches are selected by the linked immutable event gates.\nlocal s=data.jacobRokkon\nlocal now=Now()\nlocal function fresh(kind,boss)\n s.moko={kind=kind,boss=boss,tells={},tethers={},clones={},hands={},archers={},untilTime=now+65000,revision=0,phase=0}\n return s.moko\nend\nif MOKO_EVENT=='channel' then\n local id=eventArgs.spellID;local e=TensorCore.mGetEntity(eventArgs.entityID)\n if not e then return end\n local finish=now+(eventArgs.channelTimeMax+.3)*1000\n local m=s.moko\n if id==34195 then m=fresh('soldiers',e.id)\n elseif id==34201 then m=fresh('scarlet',e.id)\n elseif id==34247 then\n  if not m or m.kind~='soldiers' or now>m.untilTime then m=fresh('shadow',e.id)end\n elseif id==34270 or id==34314 then\n  if not m or m.kind~='shadow' or m.roundStart and now-m.roundStart>10000 then m=fresh('shadow',e.id)end\n  m.roundStart=now\n elseif id==34242 then\n  if not m or m.kind~='scarlet' or now>m.untilTime then m=fresh('scarlet',e.id)end\n  m.jumpAt=finish;m.untilTime=finish+18000\n elseif id==34248 then\n  if m then m.jumpAt=finish;m.untilTime=finish+15000 end\n elseif id==34264 or id==34265 then\n  if m then m.near=id==34265;m.baitAt=finish;m.boss=e.id;m.revision=m.revision+1 end\n elseif id==35873 then\n  if m then m.hands[e.id]={kind='cone',pos={x=e.pos.x,y=e.pos.y,z=e.pos.z},heading=e.pos.h,r=27,angle=math.pi,deadline=finish};m.revision=m.revision+1 end\n elseif id==34260 or id==34307 then\n  if jacobRokkonOptions.mokoBackups then\n   -- A small safe-centre guide avoids asserting the disputed donut boundary.\n   s.own(s.green:addTimedCircle(finish-now,e.pos.x,e.pos.y,e.pos.z,5,0,false,true),finish)\n   s.timer(finish-now,e.pos,0xFF33FF33);s.call('Azure: IN',false)\n  end\n elseif id==34275 or id==34317 then\n  if jacobRokkonOptions.mokoBackups then\n   s.mokoLateral={caster=e.id,target=eventArgs.targetID,deadline=finish}\n  end\n end\nelseif MOKO_EVENT=='tether' then\n local m=s.moko\n if not m or now>m.untilTime then self.used=true;return end\n local id=eventArgs.sourceEntityID\n if eventArgs.newTetherID==17 then\n  m.tethers[id]=eventArgs.newTargetID;m.clones[id]=m.clones[id]or{hits=0}\n  m.revision=m.revision+1;m.plan=nil;m.planAttempt=nil\n elseif eventArgs.oldTetherID==17 then\n  local target=m.tethers[id] or eventArgs.oldTargetID\n  local p=TensorCore.mGetEntity(target);local c=m.clones[id]or{hits=0};m.clones[id]=c\n  if p then\n   local back=m.kind=='scarlet'and 3 or 1\n   c.pos={x=p.pos.x-back*math.sin(p.pos.h),y=p.pos.y,z=p.pos.z-back*math.cos(p.pos.h)}\n   c.heading=p.pos.h;c.target=target;c.deadline=now+2700;c.locked=true\n  end\n  m.lockedAt=m.lockedAt or now;m.phase=1;m.revision=m.revision+1\n end\nelseif MOKO_EVENT=='vfx' then\n local m=s.moko\n if not m or now>m.untilTime then self.used=true;return end\n local name=eventArgs.vfxName\n if name=='c601_blue_c0v' then\n  local e=TensorCore.mGetEntity(eventArgs.primaryEntityID)\n  if e then m.blue={x=e.pos.x,y=e.pos.y,z=e.pos.z};m.revision=m.revision+1;m.plan=nil;m.planAttempt=nil end\n else\n  local dir=name:match('m0403_stlp1([fbrl])0c0t1')\n  if dir then\n   local id=eventArgs.primaryEntityID;m.tells[id]=m.tells[id]or{}\n   local q=m.tells[id]\n   if #q<2 then q[#q+1]=({f=0,b=math.pi,r=-math.pi/2,l=math.pi/2})[dir];m.revision=m.revision+1;m.plan=nil;m.planAttempt=nil end\n  end\n end\nelseif MOKO_EVENT=='packet' then\n local id=eventArgs.aoeID;local q={x=eventArgs.x,y=eventArgs.y,z=eventArgs.z}\n local finish=eventArgs.startTime+(eventArgs.duration+.3)*1000\n if id==34262 or id==34309 then\n  local u=s.mUpwell\n  if not u or now>u.untilTime then u={initial={},lanes={},untilTime=finish+18000};s.mUpwell=u end\n  local h=eventArgs.heading;q.x=q.x+30*math.sin(h);q.z=q.z+30*math.cos(h)\n  local old=u.initial[eventArgs.entityID]\n  if old then\n   s.remove(old.uuid)\n   for i=#u.lanes,1,-1 do if u.lanes[i].source==eventArgs.entityID then s.remove(u.lanes[i].uuid);table.remove(u.lanes,i)end end\n  end\n  local a={kind='centered',pos=q,length=60,width=10,heading=h,deadline=finish,caster=eventArgs.entityID,spell=id,noTimer=true}\n  u.initial[eventArgs.entityID]=a\n  for sign=-1,1,2 do\n   local dx,dz=sign*5*math.cos(h),-sign*5*math.sin(h)\n   local x,z=q.x+dx,q.z+dz;local count=0\n   while math.abs(x+200)<19 and math.abs(z)<19 do count=count+1;x=x+dx;z=z+dz end\n   if count>0 then u.lanes[#u.lanes+1]={pos={x=q.x+dx,y=q.y,z=q.z+dz},dx=dx,dz=dz,heading=h,deadline=finish+1400,left=count,source=eventArgs.entityID}end\n  end\n  u.revision=(u.revision or 0)+1;u.untilTime=math.max(u.untilTime,finish+15000)\n else\n  local m=s.moko;if not m or now>m.untilTime then self.used=true;return end\n  local radius=({[34255]=10,[34302]=10,[34256]=20,[34303]=20,[34727]=10,[34729]=10,[34728]=20,[34730]=20})[id]\n  if radius then\n   local second=id==34727 or id==34728 or id==34729 or id==34730\n   local old=m.archers[eventArgs.entityID];if old then s.remove(old.uuid)end\n   m.archers[eventArgs.entityID]={kind='circle',pos=q,r=radius,deadline=finish,second=second,spell=id}\n   m.revision=m.revision+1;m.plan=nil;m.planAttempt=nil\n  else\n   -- The native cone replaces a short-lived facing prediction after the jump.\n   local c=m.clones[eventArgs.entityID]\n   if c then\n    c.pos=q;c.heading=eventArgs.heading;c.headingReady=true;c.actual=true;c.deadline=finish;c.locked=true\n    c.phase=(id>=34499)and 2 or 1\n    m.phase=math.max(m.phase,c.phase);m.revision=m.revision+1\n   end\n  end\n end\nelseif MOKO_EVENT=='hit' then\n local id=eventArgs.spellID;local e=TensorCore.mGetEntity(eventArgs.entityID)\n local u=s.mUpwell\n if u and (id==34262 or id==34309)then\n  local a=u.initial[eventArgs.entityID];if a then a.done=true;s.remove(a.uuid);a.uuid=nil end\n elseif u and (id==34263 or id==34310)and e then\n  local best,dist\n  for _,l in ipairs(u.lanes)do\n   local d=(l.pos.x-e.pos.x)^2+(l.pos.z-e.pos.z)^2\n   if l.left>0 and math.abs(math.sin(l.heading-e.pos.h))<.1 and(not dist or d<dist)then best=l;dist=d end\n  end\n  if best and dist<2.25 then\n   s.remove(best.uuid);best.uuid=nil;best.left=best.left-1\n   best.pos={x=e.pos.x+best.dx,y=e.pos.y,z=e.pos.z+best.dz};best.deadline=now+2100\n   u.revision=(u.revision or 0)+1\n  end\n end\n local m=s.moko\n if not m then self.used=true;return end\n if id==34242 or id==34248 then\n  local c=m.clones[eventArgs.entityID]\n  if c and not c.locked then\n   local p=TensorCore.mGetEntity(m.tethers[eventArgs.entityID]);local back=m.kind=='scarlet'and 3 or 1\n   if p then c.pos={x=p.pos.x-back*math.sin(p.pos.h),y=p.pos.y,z=p.pos.z-back*math.cos(p.pos.h)};c.heading=p.pos.h;c.target=p.id;c.locked=true;c.deadline=now+2700 end\n  end\n  m.lockedAt=m.lockedAt or now;m.phase=1\n elseif id==34266 or id==34311 then\n  m.baitsDone=true\n elseif id==34255 or id==34256 or id==34302 or id==34303 then\n  local a=m.archers[eventArgs.entityID]\n  if a then a.deadline=now+6200;a.second=true;a.forecast=true;m.revision=m.revision+1 end\n elseif id==34727 or id==34728 or id==34729 or id==34730 then\n  local a=m.archers[eventArgs.entityID];if a then s.remove(a.uuid);m.archers[eventArgs.entityID]=nil;m.revision=m.revision+1 end\n elseif id==34268 or id==34312 then\n  s.spreads={};m.spreadDone=true;m.revision=m.revision+1;m.plan=nil;m.planAttempt=nil\n  if RokkonWorldText then RokkonWorldText.cancelEntityCountdown('rokkon-personal-spread')end\n elseif id==34269 or id==34313 then\n  s.stacks={};s.stackDeadline=nil;m.stackDone=true;m.revision=m.revision+1;m.plan=nil;m.planAttempt=nil\n elseif id==34244 or id==34245 or id==34246 or id==34294 or id==34295 or id==34296 then\n  m.cleaveDone=true;m.phase=2;m.revision=m.revision+1\n else\n  local c=m.clones[eventArgs.entityID]\n  if c then\n   local second=id==34499 or id==34500 or id==34501 or id==34502 or id==34507 or id==34508 or id==34509 or id==34510\n   c.hits=second and 2 or math.max(1,c.hits or 0);c.actual=false\n   if not second then\n    local q=m.tells[eventArgs.entityID]\n    if q and q[2] and c.heading then c.heading=c.heading+(c.headingReady and 0 or q[1])+q[2];c.headingReady=true;c.deadline=now+3100;c.phase=2 end\n   end\n   local count,firstDone=0,0\n   for _,v in pairs(m.clones)do count=count+1;if(v.hits or 0)>=1 then firstDone=firstDone+1 end end\n   if count==(m.kind=='soldiers'and 4 or 2)and firstDone==count then m.phase=2 end\n   m.revision=m.revision+1\n  end\n end\nend\nself.used=true\n",
